INSERT INTO categories (id, name, description) VALUES ('judiciary-law', 'Judiciary & Law (CLAT)', 'Legal reasoning, constitutional law, and legal GK for CLAT and judicial service exams.');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('judiciary-law-bank', NULL, 'Judiciary & Law Prep', 'law', 'shared', '2026-11-14T06:17:56.365Z', '2026-11-14T06:17:56.365Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('judiciary-law-bank', 'judiciary-law');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00001', 'judiciary-law-bank', 'Constitutional Law', 0, 0, 'What is the significance of Article 13 of the Constitution?', '**Article 13** declares that all laws in force before the commencement of the Constitution, and any law made thereafter, shall be void to the extent they are inconsistent with **Part III (Fundamental Rights)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00002', 'judiciary-law-bank', 'Constitutional Law', 0, 1, 'Which Article guarantees equality before law and equal protection of laws?', '**Article 14** guarantees that the State shall not deny to any person equality before the law or the equal protection of the laws within the territory of India.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00003', 'judiciary-law-bank', 'Constitutional Law', 0, 2, 'What does Article 15 prohibit?', '**Article 15** prohibits the State from discriminating against any citizen on grounds only of **religion, race, caste, sex, or place of birth**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00004', 'judiciary-law-bank', 'Constitutional Law', 0, 3, 'What is the scope of Article 16?', '**Article 16** guarantees **equality of opportunity** in matters of public employment and prohibits discrimination on grounds of religion, race, caste, sex, descent, place of birth, or residence.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00005', 'judiciary-law-bank', 'Constitutional Law', 0, 4, 'What right does Article 19(1)(a) protect, and what are its restrictions?', '**Article 19(1)(a)** guarantees the **freedom of speech and expression**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00006', 'judiciary-law-bank', 'Constitutional Law', 0, 5, 'What does Article 20 protect against?', '**Article 20** provides protection in respect of conviction for offences. It guarantees:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00007', 'judiciary-law-bank', 'Constitutional Law', 0, 6, 'What is the significance of Article 21 of the Constitution?', '**Article 21** states that no person shall be deprived of his **life or personal liberty** except according to **procedure established by law**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00008', 'judiciary-law-bank', 'Constitutional Law', 0, 7, 'What does Article 21A guarantee?', '**Article 21A**, inserted by the **86th Constitutional Amendment Act, 2002**, guarantees the **right to free and compulsory education** to all children between the ages of **6 and 14 years**, in such manner as the State may, by law, determine.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00009', 'judiciary-law-bank', 'Constitutional Law', 0, 8, 'What safeguards does Article 22 provide to arrested persons?', '**Article 22** guarantees that an arrested person must be informed of the grounds of arrest, has the right to consult and be defended by a legal practitioner of choice, and must be produced before the nearest magistrate within **24 hours** of arrest (excluding journey time).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00010', 'judiciary-law-bank', 'Constitutional Law', 0, 9, 'What does Article 23 prohibit?', '**Article 23** prohibits **traffic in human beings and begar (forced labour)**, and any contravention is an offence punishable by law.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00011', 'judiciary-law-bank', 'Constitutional Law', 0, 10, 'What does Article 24 prohibit?', '**Article 24** prohibits the employment of children below the age of **14 years** in any factory, mine, or other hazardous employment.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00012', 'judiciary-law-bank', 'Constitutional Law', 0, 11, 'What are the religious freedoms guaranteed under Article 25?', '**Article 25** guarantees to all persons freedom of conscience and the right freely to **profess, practise, and propagate religion**, subject to public order, morality, health, and other provisions of Part III.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00013', 'judiciary-law-bank', 'Constitutional Law', 0, 12, 'What is the distinction between Articles 25 and 26?', '**Article 25** protects an individual''s freedom of religion, whereas **Article 26** guarantees every **religious denomination** the right to establish and maintain institutions for religious and charitable purposes, manage its own affairs in matters of religion, and own and administer property.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00014', 'judiciary-law-bank', 'Constitutional Law', 0, 13, 'What does Article 29 protect?', '**Article 29** protects the interests of minorities by guaranteeing any section of citizens having a distinct language, script, or culture the right to **conserve** the same, and prohibits denial of admission to educational institutions maintained by the State on grounds only of religion, race, caste, or language.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00015', 'judiciary-law-bank', 'Constitutional Law', 0, 14, 'What right does Article 30 confer on minorities?', '**Article 30** gives all **religious and linguistic minorities** the right to establish and administer educational institutions of their choice, and ensures the State shall not discriminate against such institutions in granting aid on the ground that they are minority-managed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00016', 'judiciary-law-bank', 'Constitutional Law', 0, 15, 'What is the ''heart and soul'' of the Constitution according to Dr. B.R. Ambedkar?', 'Dr. **B.R. Ambedkar** described **Article 32** (the right to constitutional remedies) as the **''heart and soul'' of the Constitution**, since it guarantees the right to directly approach the **Supreme Court** for enforcement of Fundamental Rights through writs.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00017', 'judiciary-law-bank', 'Constitutional Law', 0, 16, 'What are the five writs available under Articles 32 and 226?', 'The Constitution provides for five prerogative writs:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00018', 'judiciary-law-bank', 'Constitutional Law', 0, 17, 'What is the difference between the writ jurisdiction of the Supreme Court and High Courts?', 'Under **Article 32**, the Supreme Court can issue writs **only for enforcement of Fundamental Rights**, and this right is itself a fundamental right.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00019', 'judiciary-law-bank', 'Constitutional Law', 0, 18, 'What is the nature of Directive Principles of State Policy?', '**Directive Principles of State Policy (Articles 36-51)** are **non-justiciable** guidelines directing the State to secure a just social order, though Article 37 declares them ''fundamental in the governance of the country.''
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00020', 'judiciary-law-bank', 'Constitutional Law', 0, 19, 'What does Article 39(b) and (c) direct the State to do?', '**Article 39(b)** directs the State to ensure that ownership and control of material resources are distributed to best subserve the **common good**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00021', 'judiciary-law-bank', 'Constitutional Law', 0, 20, 'What does Article 44 provide for?', '**Article 44** directs the State to endeavour to secure a **Uniform Civil Code** for citizens throughout the territory of India, placing personal laws within the ambit of future legislative harmonisation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00022', 'judiciary-law-bank', 'Constitutional Law', 0, 21, 'What does Article 50 mandate?', '**Article 50** directs the State to take steps to **separate the judiciary from the executive** in the public services of the State, aiming to ensure judicial independence at the subordinate level.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00023', 'judiciary-law-bank', 'Constitutional Law', 0, 22, 'How many Fundamental Duties are listed under Article 51A, and when were they inserted?', '**Article 51A**, inserted by the **42nd Amendment Act, 1976** on the recommendation of the **Swaran Singh Committee**, originally listed **ten Fundamental Duties**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00024', 'judiciary-law-bank', 'Constitutional Law', 0, 23, 'What is the composition and role of the Election Commission of India under Article 324?', '**Article 324** vests the **superintendence, direction, and control** of elections to Parliament, State Legislatures, and the offices of President and Vice-President in the **Election Commission of India**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00025', 'judiciary-law-bank', 'Constitutional Law', 0, 24, 'What is the procedure for impeachment of the President under Article 61?', 'Under **Article 61**, the President may be removed for **''violation of the Constitution''** through impeachment. The charge may be initiated in either House of Parliament after 14 days'' notice signed by at least one-quarter of its members, and must be passed by a **two-thirds majority** of the total membership of that House.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00026', 'judiciary-law-bank', 'Constitutional Law', 0, 25, 'What are the qualifications to become President of India under Article 58?', 'Under **Article 58**, a person must be a **citizen of India**, have completed **35 years of age**, and be qualified for election as a member of the **Lok Sabha**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00027', 'judiciary-law-bank', 'Constitutional Law', 0, 26, 'What is the extent of the President''s pardoning power under Article 72?', '**Article 72** empowers the President to grant **pardons, reprieves, respites, or remissions** of punishment, or to suspend, remit, or commute sentences in cases of (i) court-martial, (ii) offences against Union laws, and (iii) **death sentences** — even where the offence falls under State law.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00028', 'judiciary-law-bank', 'Constitutional Law', 0, 27, 'What is the ordinance-making power of the President under Article 123?', '**Article 123** empowers the President to promulgate **ordinances** when Parliament is not in session, if satisfied that circumstances exist which render immediate action necessary.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00029', 'judiciary-law-bank', 'Constitutional Law', 0, 28, 'What are the three types of Emergency recognised under the Constitution?', 'The Constitution recognises three kinds of Emergency:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00030', 'judiciary-law-bank', 'Constitutional Law', 0, 29, 'What changed in Article 352 after the 44th Amendment?', 'Originally, ''internal disturbance'' was a ground for National Emergency; the **44th Amendment Act, 1978** replaced it with **''armed rebellion''** to prevent misuse, following the experience of the 1975 Emergency.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00031', 'judiciary-law-bank', 'Constitutional Law', 0, 30, 'What is the effect of a National Emergency on Fundamental Rights?', 'During a National Emergency under **Article 358**, **Article 19** rights are automatically suspended.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00032', 'judiciary-law-bank', 'Constitutional Law', 0, 31, 'What is the significance of the case ADM Jabalpur v. Shivkant Shukla (1976) regarding Article 21?', 'In **ADM Jabalpur v. Shivkant Shukla (1976)**, a majority of the Supreme Court controversially held that during an Emergency, the **right to move any court for enforcement of Article 21 remained suspended**, even against illegal detention.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00033', 'judiciary-law-bank', 'Constitutional Law', 0, 32, 'What is the procedure for imposing President''s Rule under Article 356?', '**Article 356** allows the President, on receipt of a report from the Governor or otherwise, to assume to himself the functions of the State Government if satisfied that governance cannot be carried on in accordance with constitutional provisions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00034', 'judiciary-law-bank', 'Constitutional Law', 0, 33, 'What did the Supreme Court hold in S.R. Bommai v. Union of India (1994)?', 'In ***S.R. Bommai v. Union of India* (1994)**, a nine-judge bench held that the proclamation of President''s Rule under **Article 356** is subject to **judicial review**, and that a **floor test** in the Assembly, not the Governor''s subjective satisfaction, is the proper test of majority.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00035', 'judiciary-law-bank', 'Constitutional Law', 0, 34, 'What is the composition of the Supreme Court under Article 124?', '**Article 124** provides for a Supreme Court consisting of the **Chief Justice of India** and such number of other judges as Parliament may by law prescribe, currently fixed at a maximum strength of **34 judges** (including the CJI) by statute.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00036', 'judiciary-law-bank', 'Constitutional Law', 0, 35, 'What is the retirement age for Supreme Court and High Court judges?', 'A Supreme Court judge retires at the age of **65 years** (**Article 124**), while a High Court judge retires at the age of **62 years** (**Article 217**), the latter age having been raised from 60 to 62 by the **15th Amendment Act, 1963**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00037', 'judiciary-law-bank', 'Constitutional Law', 0, 36, 'What is the procedure for removal of a Supreme Court or High Court judge?', 'A judge of the Supreme Court or High Court can be removed only on grounds of **proved misbehaviour or incapacity**, through a motion passed by a **special majority** in each House of Parliament (majority of total membership and two-thirds of members present and voting), followed by the President''s order, as per **Articles 124(4) and 218**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00038', 'judiciary-law-bank', 'Constitutional Law', 0, 37, 'What is the concept of ''collegium system'' in judicial appointments?', 'The **collegium system** is a judicially evolved mechanism (not mentioned in the Constitution text) under which appointments and transfers of judges of the Supreme Court and High Courts are decided by the **Chief Justice of India and a group of senior-most Supreme Court judges**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00039', 'judiciary-law-bank', 'Constitutional Law', 0, 38, 'What is the significance of Article 131?', '**Article 131** grants the Supreme Court **original jurisdiction** in disputes between the Government of India and one or more States, or between States themselves, where the dispute involves a question of law or fact on which the existence or extent of a legal right depends.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00040', 'judiciary-law-bank', 'Constitutional Law', 0, 39, 'What is the appellate jurisdiction of the Supreme Court under Article 136?', '**Article 136** empowers the Supreme Court to grant **Special Leave to Appeal** from any judgment, decree, determination, sentence, or order passed by any court or tribunal in India (except military tribunals/courts martial).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00041', 'judiciary-law-bank', 'Constitutional Law', 0, 40, 'What power does Article 142 confer upon the Supreme Court?', '**Article 142** empowers the Supreme Court to pass any **decree or order necessary for doing complete justice** in any cause or matter pending before it, and such orders are enforceable throughout India.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00042', 'judiciary-law-bank', 'Constitutional Law', 0, 41, 'What is the significance of Article 143?', '**Article 143** empowers the President to seek the **advisory opinion of the Supreme Court** on questions of law or fact of public importance. The Court''s opinion under this provision is advisory and **not binding**, unlike its judgments in ordinary adjudication.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00043', 'judiciary-law-bank', 'Constitutional Law', 0, 42, 'What is judicial review and where is it rooted in the Indian Constitution?', '**Judicial review** is the power of courts to examine the constitutionality of legislative and executive actions and declare them void if inconsistent with the Constitution.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00044', 'judiciary-law-bank', 'Constitutional Law', 0, 43, 'What is the ''basic structure doctrine''?', 'The **basic structure doctrine**, propounded in *Kesavananda Bharati v. State of Kerala* (1973), holds that Parliament''s power to amend the Constitution under **Article 368** is wide but not unlimited — it **cannot alter or destroy the Constitution''s basic structure**, which includes features like supremacy of the Constitution, separation of powers, judicial review, federalism, secularism, and free and fair elections.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00045', 'judiciary-law-bank', 'Constitutional Law', 0, 44, 'What is the distinction between the Union, State, and Concurrent Lists under the Seventh Schedule?', 'The **Seventh Schedule** divides legislative subjects into three lists: the **Union List** (List I) on which only Parliament can legislate (e.g., defence, foreign affairs), the **State List** (List II) on which only State legislatures can normally legislate (e.g., police, public health), and the **Concurrent List** (List III) on which both Parliament and State legislatures can legislate (e.g., criminal law, marriage, education).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00046', 'judiciary-law-bank', 'Constitutional Law', 0, 45, 'What happens in case of a conflict between Union and State laws on a Concurrent List subject?', 'Under **Article 254**, if a State law conflicts with a Union law on a Concurrent List subject, the **Union law prevails** and the State law is void to the extent of the repugnancy — **unless** the State law has received the **President''s assent** under Article 254(2), in which case it prevails in that State, though Parliament can still override it by a subsequent law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00047', 'judiciary-law-bank', 'Constitutional Law', 0, 46, 'What is the residuary power of legislation, and where does it lie?', 'Under **Article 248**, read with **Entry 97 of the Union List**, the **residuary power** to legislate on any matter not enumerated in the State or Concurrent Lists vests exclusively in **Parliament**, reflecting India''s leaning towards a strong Centre within its federal structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00048', 'judiciary-law-bank', 'Constitutional Law', 0, 47, 'What is the significance of Articles 352-360 collectively?', '**Articles 352 to 360** form **Part XVIII** of the Constitution dealing with **Emergency Provisions**, enabling a shift from the federal to a unitary character of governance during war, breakdown of State machinery, or financial instability — a feature often cited to describe India as ''quasi-federal'' or having ''federalism with a unitary bias''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00049', 'judiciary-law-bank', 'Constitutional Law', 0, 48, 'What is the procedure for amending the Constitution under Article 368?', '**Article 368** provides three methods of amendment: by a **simple majority** of Parliament (for matters not covered by Article 368 itself, like formation of new states), by a **special majority** (majority of total membership and two-thirds of members present and voting in each House), and by a **special majority plus ratification by half the State legislatures** for federal provisions like the distribution of legislative powers or representation of States.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00050', 'judiciary-law-bank', 'Constitutional Law', 0, 49, 'What is the Ninth Schedule and its relevance to judicial review?', 'The **Ninth Schedule**, inserted by the **First Amendment Act, 1951**, originally granted immunity from judicial review to laws placed within it (mainly land reform laws), by virtue of **Article 31B**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00051', 'judiciary-law-bank', 'Constitutional Law', 0, 50, 'What is the Panchayati Raj system, and which amendment gave it constitutional status?', 'The **73rd Constitutional Amendment Act, 1992** gave constitutional status to **Panchayati Raj institutions** by inserting **Part IX (Articles 243-243O)** and the **Eleventh Schedule**, establishing a three-tier system of rural local self-government with mandatory elections every five years through State Election Commissions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00052', 'judiciary-law-bank', 'Constitutional Law', 0, 51, 'Which amendment gave constitutional status to Urban Local Bodies?', 'The **74th Constitutional Amendment Act, 1992** inserted **Part IXA (Articles 243P-243ZG)** and the **Twelfth Schedule**, granting constitutional status to **Municipalities** (Nagar Panchayats, Municipal Councils, and Municipal Corporations) as institutions of urban local self-governance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00053', 'judiciary-law-bank', 'Constitutional Law', 0, 52, 'What is the significance of Article 370 and its special status?', '**Article 370**, a temporary provision, granted special autonomous status to the State of **Jammu and Kashmir**, limiting Parliament''s legislative competence over the State mainly to defence, foreign affairs, and communications, unless the State concurred otherwise.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00054', 'judiciary-law-bank', 'Constitutional Law', 0, 53, 'What is the role of the Governor under Article 163?', '**Article 163** provides that the Governor acts with the **aid and advice of the Council of Ministers** headed by the Chief Minister, except in matters where the Constitution requires the Governor to act in his own **discretion**, such as reserving a bill for the President''s consideration.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00055', 'judiciary-law-bank', 'Constitutional Law', 0, 54, 'What is the significance of the Preamble to the Constitution?', 'The **Preamble** declares India to be a **Sovereign, Socialist, Secular, Democratic Republic** securing Justice, Liberty, Equality, and Fraternity to all citizens. The words ''Socialist'' and ''Secular'' were added by the **42nd Amendment Act, 1976**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00056', 'judiciary-law-bank', 'Constitutional Law', 0, 55, 'Can the Preamble be amended, and is it enforceable in court?', 'Yes, the Preamble can be **amended under Article 368**, as confirmed in *Kesavananda Bharati* (1973), since it is part of the Constitution, though subject to the basic structure limitation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00057', 'judiciary-law-bank', 'Constitutional Law', 0, 56, 'What is the composition of the Rajya Sabha under Article 80?', '**Article 80** provides that the Rajya Sabha shall consist of not more than **250 members**, of whom up to **12 are nominated** by the President for their special knowledge in literature, science, art, or social service, and the rest are elected by elected members of State Legislative Assemblies through proportional representation by single transferable vote.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00058', 'judiciary-law-bank', 'Constitutional Law', 0, 57, 'What is the procedure for a Money Bill under Article 110?', '**Article 110** defines a **Money Bill** as one containing only provisions dealing with taxation, borrowing, or the Consolidated Fund. It can be introduced **only in the Lok Sabha**, and the Rajya Sabha can only make recommendations within 14 days, which the Lok Sabha may accept or reject; a Money Bill cannot be rejected or indefinitely delayed by the Rajya Sabha.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00059', 'judiciary-law-bank', 'Constitutional Law', 0, 58, 'What is a ''Confidence Motion'' and ''No-Confidence Motion'' in the context of parliamentary government?', 'A **No-Confidence Motion** is moved by the Opposition against the Council of Ministers to test whether it enjoys majority support in the Lok Sabha; if passed, the government must resign.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00060', 'judiciary-law-bank', 'Constitutional Law', 0, 59, 'What does Article 75(3) establish?', '**Article 75(3)** establishes the principle of **collective responsibility** of the Council of Ministers to the **Lok Sabha**, meaning the entire Council stands or falls together based on the confidence of the House, even if an individual minister''s department is at issue.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00061', 'judiciary-law-bank', 'Constitutional Law', 0, 60, 'What is the anti-defection law, and under which Schedule is it placed?', 'The **anti-defection law** is contained in the **Tenth Schedule**, inserted by the **52nd Amendment Act, 1985**. It disqualifies a member of Parliament or a State Legislature from continuing as a member if they voluntarily give up membership of their political party or vote/abstain contrary to a party whip without prior permission, subject to limited exceptions like a merger of parties.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00062', 'judiciary-law-bank', 'Constitutional Law', 0, 61, 'What was decided in Kihoto Hollohan v. Zachillhu (1992) regarding the anti-defection law?', 'In ***Kihoto Hollohan v. Zachillhu* (1992)**, the Supreme Court upheld the constitutional validity of the **Tenth Schedule**, holding that the Speaker/Chairman''s decision on disqualification is subject to **judicial review** on limited grounds such as mala fides, perversity, or violation of natural justice, since the Speaker acts as a tribunal while deciding such matters.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00063', 'judiciary-law-bank', 'Constitutional Law', 0, 62, 'What is the significance of Article 356 being termed a ''dead letter'' recommendation by the Sarkaria Commission?', 'The **Sarkaria Commission (1988)** on Centre-State relations recommended that **Article 356** be used only as a **''measure of last resort''**, after all other options to resolve a constitutional breakdown in a State have failed, to prevent its misuse for political purposes — a recommendation substantially endorsed by the Supreme Court in *S.R. Bommai* (1994).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00064', 'judiciary-law-bank', 'Constitutional Law', 0, 63, 'What is the function of the Finance Commission under Article 280?', '**Article 280** provides for the constitution of a **Finance Commission** every five years (or earlier) by the President to recommend the distribution of net tax proceeds between the Union and the States, the principles governing grants-in-aid, and measures to augment the resources of Panchayats and Municipalities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00065', 'judiciary-law-bank', 'Constitutional Law', 0, 64, 'What is the Comptroller and Auditor General''s role under Article 148?', '**Article 148** establishes the office of the **Comptroller and Auditor General (CAG) of India**, who audits all receipts and expenditure of the Union and State Governments and submits reports to the President/Governor, which are laid before Parliament/State Legislature. The CAG is often described as the ''guardian of the public purse.''', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00066', 'judiciary-law-bank', 'Constitutional Law', 0, 65, 'What is the significance of Article 300A?', '**Article 300A**, inserted by the **44th Amendment Act, 1978**, provides that no person shall be deprived of his **property save by authority of law**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00067', 'judiciary-law-bank', 'Constitutional Law', 0, 66, 'What is the position of the Attorney General of India under Article 76?', '**Article 76** provides for the **Attorney General of India**, the highest law officer, appointed by the President, who must be qualified to be a Supreme Court judge. The Attorney General advises the Government of India on legal matters and has the right to appear in any court in India, and also has the right to speak in and participate in the proceedings of either House of Parliament without a vote.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00068', 'judiciary-law-bank', 'Constitutional Law', 0, 67, 'What is the quorum requirement for Parliament under Article 100?', '**Article 100** fixes the quorum to constitute a meeting of either House of Parliament at **one-tenth of the total number of members** of that House, including the presiding officer.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00069', 'judiciary-law-bank', 'Constitutional Law', 0, 68, 'What is the ''doctrine of severability'' in constitutional law?', 'The **doctrine of severability**, recognised under **Article 13**, holds that when a part of a statute is unconstitutional, only the **offending/invalid portion is struck down**, provided it can be separated from the valid part without affecting the legislative intent; if inseverable, the entire statute falls.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00070', 'judiciary-law-bank', 'Constitutional Law', 0, 69, 'What is the ''doctrine of eclipse''?', 'The **doctrine of eclipse** holds that a pre-constitutional law inconsistent with Fundamental Rights is not void ab initio but becomes **''eclipsed''** or dormant to the extent of the inconsistency; it remains valid for past transactions and can revive if the relevant Fundamental Right is subsequently amended to remove the inconsistency.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00071', 'judiciary-law-bank', 'Constitutional Law', 0, 70, 'What is a ''money bill'' versus a ''financial bill'' under the Constitution?', 'A **Money Bill (Article 110)** deals exclusively with specified financial matters like taxation and the Consolidated Fund, and can be certified as such only by the **Lok Sabha Speaker**; it follows the restrictive procedure limiting Rajya Sabha''s role.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00072', 'judiciary-law-bank', 'Constitutional Law', 0, 71, 'What is the significance of Article 143 being advisory versus Article 32 being a binding remedy?', 'Under **Article 143**, the Supreme Court''s opinion given on a Presidential reference is **advisory** and not binding as a judicial precedent, whereas relief granted under **Article 32** in actual litigation results in a **binding judgment** enforceable against the parties and having precedential value under Article 141.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00073', 'judiciary-law-bank', 'Constitutional Law', 0, 72, 'What is the ''doctrine of pith and substance''?', 'The **doctrine of pith and substance** is used to determine the true nature and character of a legislation to decide under which legislative list it falls, in cases of apparent overlap between Union and State lists. If the true essence of law falls within the competent legislature''s domain, incidental encroachment into another list does not render it invalid.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00074', 'judiciary-law-bank', 'Constitutional Law', 0, 73, 'What is the ''doctrine of colourable legislation''?', 'The **doctrine of colourable legislation** means that a legislature cannot do indirectly what it is not permitted to do directly. If a law, though apparently within the legislature''s competence, is in substance and effect designed to achieve something outside its competence, it will be struck down as a fraud on the Constitution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00075', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 0, 'What does the maxim ''Audi Alteram Partem'' mean?', '**Audi Alteram Partem** means **''hear the other side''**. It is a cornerstone principle of **natural justice**, requiring that no person should be condemned or adversely affected by a decision without being given a fair opportunity to present their case.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00076', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 1, 'What does the maxim ''Nemo Judex in Causa Sua'' mean?', '**Nemo Judex in Causa Sua** means **''no one should be a judge in his own cause''**. It embodies the **rule against bias**, requiring that an adjudicator must be impartial and have no personal interest in the outcome of the case he is deciding.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00077', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 2, 'What is the meaning of ''Ignorantia Juris Non Excusat''?', '**Ignorantia Juris Non Excusat** means **''ignorance of law is no excuse''**. It is a foundational principle of criminal and general jurisprudence, holding that a person cannot avoid liability by claiming they were unaware that their act was prohibited by law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00078', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 3, 'What does ''Actus Non Facit Reum Nisi Mens Sit Rea'' mean?', 'This maxim means **''an act does not make a person guilty unless the mind is also guilty''**. It underlines that criminal liability generally requires both a **guilty act (actus reus)** and a **guilty mind (mens rea)**, except in cases of strict or absolute liability offences.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00079', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 4, 'What is the meaning of ''Res Ipsa Loquitur''?', '**Res Ipsa Loquitur** means **''the thing speaks for itself''**. It is a rule of evidence in the law of torts (negligence) where the very nature of an accident implies negligence on the defendant''s part, shifting the burden to the defendant to explain how the incident occurred without their fault.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00080', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 5, 'What does ''Volenti Non Fit Injuria'' mean?', '**Volenti Non Fit Injuria** means **''to a willing person, no injury is done''**. It is a defence in tort law whereby a person who voluntarily consents to or assumes a known risk cannot later claim damages for harm resulting from that risk.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00081', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 6, 'What is the meaning of ''Ubi Jus Ibi Remedium''?', '**Ubi Jus Ibi Remedium** means **''where there is a right, there is a remedy''**. It signifies that the law provides a remedy whenever a legal right is violated, forming the basis for civil actions and relief.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00082', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 7, 'What does ''Qui Facit Per Alium Facit Per Se'' mean?', 'This maxim means **''he who acts through another is deemed to act himself''**. It forms the basis of **vicarious liability**, particularly the liability of an employer/principal for the wrongful acts of an employee/agent done within the course of employment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00083', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 8, 'What is the meaning of ''Respondeat Superior''?', '**Respondeat Superior** means **''let the superior/master answer''**. It is the doctrine underlying an employer''s **vicarious liability** for torts committed by employees acting within the scope of their employment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00084', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 9, 'What does ''Damnum Sine Injuria'' mean?', '**Damnum Sine Injuria** means **''damage without legal injury''**. It refers to situations where a person suffers actual loss or harm, but since no legal right has been infringed, no action lies in tort — as illustrated in *Gloucester Grammar School Case* (1410).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00085', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 10, 'What does ''Injuria Sine Damno'' mean?', '**Injuria Sine Damno** means **''legal injury without actual damage''**. It refers to the violation of a legal right even though no actual loss has resulted, and the law still permits an action, since every injury to a legal right is actionable per se — as illustrated in *Ashby v. White* (1703).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00086', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 11, 'What is the meaning of ''Ex Turpi Causa Non Oritur Actio''?', 'This maxim means **''no action arises from a base/illegal cause''**. It prevents a person from basing a civil claim on their own illegal or immoral act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00087', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 12, 'What does ''Delegatus Non Potest Delegare'' signify?', '**Delegatus Non Potest Delegare** means **''a delegate cannot further delegate''**. It signifies that a person to whom power or function has been delegated cannot, in the absence of express authorisation, sub-delegate that power to another.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00088', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 13, 'What is the meaning of ''Ratio Decidendi''?', '**Ratio Decidendi** means **''the reason for the decision''**. It refers to the legal principle or rule on which a court''s judgment is based, which has binding precedential value under the doctrine of stare decisis, as distinguished from **obiter dicta**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00089', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 14, 'What is ''Obiter Dicta''?', '**Obiter Dicta** refers to observations or remarks made by a judge in a judgment that are **not essential** to the decision of the case. While persuasive, they are **not binding precedent**, unlike the ratio decidendi.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00090', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 15, 'What does ''Stare Decisis'' mean?', '**Stare Decisis** means **''to stand by things decided''**. It is the doctrine of **binding precedent**, requiring courts to follow principles laid down in earlier decisions of higher or the same courts in similar cases, ensuring consistency and predictability in law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00091', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 16, 'What does ''Pacta Sunt Servanda'' mean?', '**Pacta Sunt Servanda** means **''agreements must be kept''**. It is a fundamental principle of contract law and international law, holding that valid agreements/treaties are binding on the parties and must be performed in good faith.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00092', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 17, 'What is the meaning of ''Caveat Emptor''?', '**Caveat Emptor** means **''let the buyer beware''**. It places the onus on a buyer to examine and satisfy themselves about the quality and suitability of goods before purchase, subject to statutory exceptions such as implied conditions/warranties under the Sale of Goods Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00093', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 18, 'What does ''Caveat Venditor'' mean?', '**Caveat Venditor** means **''let the seller beware''**, the converse of caveat emptor. It reflects the modern consumer-protection trend placing greater responsibility on sellers to ensure goods/services meet promised standards, as embodied in the Consumer Protection Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00094', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 19, 'What is the meaning of ''De Minimis Non Curat Lex''?', '**De Minimis Non Curat Lex** means **''the law does not concern itself with trifles''**. Courts will not entertain matters involving negligible or trivial harm, and the principle is also reflected in **Section 95 of the Indian Penal Code** (now Section 22 BNS), which exempts trivial acts from criminal liability.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00095', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 20, 'What does ''Mens Rea'' mean, and why is it important?', '**Mens Rea** means **''guilty mind''**. It refers to the criminal intent or knowledge of wrongdoing accompanying an act, and is a necessary element for most criminal offences, captured in the maxim actus non facit reum nisi mens sit rea.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00096', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 21, 'What does ''Actus Reus'' mean?', '**Actus Reus** means **''guilty act''**. It refers to the physical act or omission that constitutes the external, conduct element of a crime, which must combine with mens rea to establish criminal liability (except in strict liability offences).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00097', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 22, 'What is the meaning of ''Novus Actus Interveniens''?', '**Novus Actus Interveniens** means **''a new intervening act''**. It refers to an independent event that breaks the chain of causation between the defendant''s original act and the resulting harm, potentially absolving the defendant of liability for the ultimate consequence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00098', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 23, 'What does ''Doli Incapax'' mean?', '**Doli Incapax** means **''incapable of crime''**. It is a legal presumption that children below a certain age (in India, under **Section 82 of the IPC**/Section 20 BNS for children under 7, and conditionally under Section 83 IPC/Section 21 BNS for 7-12 years) lack the mental capacity to form criminal intent.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00099', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 24, 'What is the meaning of ''In Pari Delicto''?', '**In Pari Delicto** means **''in equal fault''**. It is a legal doctrine under which a court will not assist either party to an illegal or wrongful transaction when both are equally culpable, leaving losses to lie where they fall.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00100', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 25, 'What does ''Uberrimae Fidei'' mean?', '**Uberrimae Fidei** means **''of utmost good faith''**. Certain contracts, notably contracts of insurance, are classified as contracts of utmost good faith, requiring full and honest disclosure of all material facts by both parties.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00101', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 26, 'What is the meaning of ''Quid Pro Quo''?', '**Quid Pro Quo** means **''something for something''**. It reflects the concept of **consideration** in contract law — a benefit or detriment exchanged between parties as the price for which the promise is bought.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00102', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 27, 'What does ''Ejusdem Generis'' mean as a rule of interpretation?', '**Ejusdem Generis** means **''of the same kind or class''**. It is a rule of statutory interpretation whereby general words following specific words of a particular class are construed as limited to things of the same kind as those specifically enumerated.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00103', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 28, 'What is the ''Noscitur a Sociis'' rule of interpretation?', '**Noscitur a Sociis** means **''a word is known by the company it keeps''**. This interpretive rule holds that the meaning of an ambiguous word can be determined by reference to the words surrounding it in the same provision or context.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00104', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 29, 'What is the ''Golden Rule'' of interpretation?', 'The **Golden Rule** of interpretation requires courts to give words their plain, ordinary (literal) meaning unless doing so would lead to an **absurdity, repugnancy, or inconsistency**, in which case the meaning may be modified only to the extent necessary to avoid that absurd result.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00105', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 30, 'What is the ''Mischief Rule'' of interpretation (Heydon''s Rule)?', 'The **Mischief Rule**, laid down in *Heydon''s Case* (1584), requires courts to examine four things: what was the common law before the statute, what was the mischief/defect the common law did not address, what remedy Parliament resolved to cure the mischief, and the true reason for that remedy — and to construe the statute so as to suppress the mischief and advance the remedy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00106', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 31, 'What is the ''Literal Rule'' of interpretation?', 'The **Literal Rule** requires that words of a statute be given their **plain, grammatical, and ordinary meaning**, even if the result seems harsh, provided the language is clear and unambiguous — on the premise that the legislature''s intent is best reflected in the words it actually used.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00107', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 32, 'What does ''Expressio Unius Est Exclusio Alterius'' mean?', 'This maxim means **''the express mention of one thing excludes others''**. When a statute specifically enumerates certain things, it is presumed that items not mentioned were intentionally excluded from its scope.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00108', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 33, 'What does ''Generalia Specialibus Non Derogant'' mean?', 'This maxim means **''general things do not derogate from special things''**. When there is a conflict between a general provision and a special provision on the same subject, the **special provision prevails**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00109', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 34, 'What is the meaning of ''Lex Non Cogit Ad Impossibilia''?', 'This maxim means **''the law does not compel the impossible''**. It recognises that a person cannot be held liable for failing to perform an act that is impossible to perform.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00110', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 35, 'What does ''Nemo Dat Quod Non Habet'' mean?', 'This maxim means **''no one can give what they do not have''**. In the law of sale of goods, a seller generally cannot pass a better title to goods than they themselves possess, subject to statutory exceptions (e.g., sale in market overt, sale by a mercantile agent).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00111', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 36, 'What is the meaning of ''Res Judicata''?', '**Res Judicata** means **''a matter already judged''**. Codified under **Section 11 of the Code of Civil Procedure, 1908**, it bars the trial of a suit or issue that has already been directly and substantially decided by a competent court in a former suit between the same parties.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00112', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 37, 'What does ''Sub Judice'' mean?', '**Sub Judice** means **''under judgment''**, referring to a matter that is currently pending before a court and has not yet been finally decided. Public comment on sub judice matters may attract contempt of court.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00113', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 38, 'What is the meaning of ''Amicus Curiae''?', '**Amicus Curiae** means **''friend of the court''**. It refers to a person, often a senior advocate, appointed or permitted by a court to assist it with expert or impartial legal submissions on a case, especially where a party is unrepresented or the matter has wide public importance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00114', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 39, 'What does ''Locus Standi'' mean?', '**Locus Standi** means **''place of standing''**, i.e., the legal right or capacity of a person to bring an action or appear in a court. Indian courts have relaxed strict locus standi requirements through **Public Interest Litigation (PIL)**, allowing any public-spirited person to move the court on behalf of those unable to do so themselves.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00115', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 40, 'What is the meaning of ''Mandamus''?', '**Mandamus** means **''we command''**. It is a writ issued by a superior court directing a public authority, tribunal, or inferior court to perform a public or statutory duty which it has failed or refused to perform.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00116', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 41, 'What does ''Certiorari'' mean as a writ?', '**Certiorari** means **''to be certified/informed''**. It is a writ issued by a higher court to quash an order or decision of a lower court, tribunal, or authority that has acted without or in excess of jurisdiction, or in violation of natural justice.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00117', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 42, 'What does ''Habeas Corpus'' mean?', '**Habeas Corpus** means **''you may have the body''**. It is a writ directing that a person who has been detained be produced before the court so that the legality of their detention can be examined, and an illegally detained person be set at liberty.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00118', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 43, 'What does ''Quo Warranto'' mean?', '**Quo Warranto** means **''by what authority''**. It is a writ used to question the legal right of a person to hold a public office, and can result in that person being ousted if they are found to be occupying the office without legal authority.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00119', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 44, 'What does ''Prohibition'' mean as a writ?', 'The writ of **Prohibition** is issued by a superior court to a lower court or tribunal to **prevent** it from continuing proceedings in excess of its jurisdiction or in violation of natural justice, before the lower court renders its decision — unlike certiorari, which is issued after a decision has been made.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00120', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 45, 'What is the meaning of ''Ratio Legis''?', '**Ratio Legis** means **''the reason/rationale of the law''**. It refers to the underlying purpose or legislative intent behind a statutory provision, used as an aid to purposive interpretation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00121', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 46, 'What does ''Casus Omissus'' mean?', '**Casus Omissus** means **''a case omitted''**. It refers to a situation not provided for by a statute, i.e., a gap or lacuna in the legislation, which courts generally cannot fill by implication but may draw attention to for legislative correction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00122', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 47, 'What does ''Functus Officio'' mean?', '**Functus Officio** means **''having performed/discharged the office''**. It refers to an authority or court that has completed its function or duty and therefore no longer has the jurisdiction to act further in the same matter, such as a court that has already pronounced its final judgment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00123', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 48, 'What is the meaning of ''Doli Capax''?', '**Doli Capax** means **''capable of crime''**. It refers to a person (typically a child above the statutorily specified age) who is presumed to possess sufficient understanding to distinguish right from wrong and can therefore be held criminally responsible for their acts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00124', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 49, 'What does ''Bona Fide'' mean?', '**Bona Fide** means **''in good faith''**. It describes an act done honestly, without deceit, fraud, or any intention to take unfair advantage of another person.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00125', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 50, 'What does ''Mala Fide'' mean?', '**Mala Fide** means **''in bad faith''**. In administrative law, an action taken mala fide — for an improper purpose, with dishonest intent, or for extraneous/collateral considerations — can be struck down as an abuse of power, even if the authority technically possessed the power.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00126', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 51, 'What does ''Ultra Vires'' mean?', '**Ultra Vires** means **''beyond the powers''**. It refers to an act performed by a person or body (e.g., a company, statutory authority, or delegated legislation) that exceeds the legal authority or powers conferred upon it, rendering the act void.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00127', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 52, 'What is the meaning of ''Intra Vires''?', '**Intra Vires** means **''within the powers''**, the opposite of ultra vires. It describes an act that is performed within the legal authority or jurisdiction validly conferred on the person or body performing it.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00128', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 53, 'What does ''Sine Die'' mean?', '**Sine Die** means **''without a day''**, i.e., indefinitely, without fixing a date for resumption. A legislative session adjourned sine die has no fixed date set for reassembly.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00129', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 54, 'What is the meaning of ''Ad Interim''?', '**Ad Interim** means **''in the meantime''** or ''temporary.'' It commonly describes interim relief, such as an **ad interim injunction**, granted by a court on a temporary basis pending final disposal of the matter.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00130', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 55, 'What does ''Prima Facie'' mean?', '**Prima Facie** means **''at first sight/on its face''**. A prima facie case refers to evidence sufficient to establish a fact or raise a presumption unless rebutted — enough to proceed to trial or justify further legal action, without being conclusive proof.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00131', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 56, 'What does ''De Facto'' mean, as opposed to ''De Jure''?', '**De Facto** means **''in fact''**, describing a state of affairs existing in practice, regardless of legal recognition. **De Jure** means **''by law/right''**, describing something recognised and sanctioned by law — for instance, a de facto government exercises actual control, while a de jure government has lawful authority.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00132', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 57, 'What does ''Per Incuriam'' mean?', '**Per Incuriam** means **''through lack of care''**. A judgment is said to be rendered per incuriam when it is passed in ignorance of a binding statutory provision or precedent, and such a decision is **not binding** as authoritative precedent.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00133', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 58, 'What does ''Sui Generis'' mean?', '**Sui Generis** means **''of its own kind''** or unique. It describes a legal category, right, or classification that is distinct and cannot be subsumed under any existing category — for example, courts have described certain constitutional rights or regulatory frameworks as sui generis.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00134', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 59, 'What is the meaning of ''Et Seq.'' or ''Et Sequentes'' used in legal citations?', '**Et Seq.** (et sequentes/sequentia) means **''and the following''**. It is used in legal citations to indicate that the reference extends to the sections or pages following the one cited, e.g., ''Section 299 et seq.''', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00135', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 60, 'What does the maxim ''Fraus Omnia Corrumpit'' mean?', '**Fraus Omnia Corrumpit** means **''fraud vitiates everything''**. It signifies that a transaction, judgment, or document obtained by fraud is void and confers no legal rights, regardless of how regular it otherwise appears.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00136', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 61, 'What does ''Lex Loci'' mean?', '**Lex Loci** means **''the law of the place''**. In private international law, it refers to the principle that the law applicable to a transaction or act is generally that of the place where it occurred (e.g., lex loci contractus for contracts, lex loci delicti for torts).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00137', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 62, 'What is the meaning of ''Nulla Poena Sine Lege''?', '**Nulla Poena Sine Lege** means **''no punishment without law''**. It is a fundamental principle of criminal jurisprudence (reflected in Article 20(1) of the Indian Constitution) that a person cannot be punished for an act that was not a criminal offence under the law at the time it was committed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00138', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 63, 'What does ''Interest Reipublicae Ut Sit Finis Litium'' mean?', 'This maxim means **''it is in the interest of the State that there be an end to litigation''**. It underlies principles like res judicata and limitation periods, which promote finality in legal proceedings and prevent endless relitigation of the same dispute.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00139', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 64, 'What is the meaning of ''Actio Personalis Moritur Cum Persona''?', 'This maxim means **''a personal right of action dies with the person''**. It traditionally held that certain personal causes of action (such as defamation) do not survive the death of the person who suffered the wrong, though this has been modified by statute in several jurisdictions, including India under certain torts legislation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00140', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 65, 'What does ''Boni Judicis Est Ampliare Jurisdictionem'' mean, and is it followed in India?', 'This maxim traditionally means **''it is the duty of a good judge to enlarge/expand jurisdiction''**, encouraging courts to take a liberal view to do justice. However, Indian courts have generally cautioned against expanding jurisdiction beyond statutory limits, preferring strict adherence to the principle that **jurisdiction cannot be conferred by consent or judicial enlargement**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00141', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 66, 'What is the meaning of ''Falsus in Uno, Falsus in Omnibus''?', 'This maxim means **''false in one thing, false in everything''**. Although recognised in some common law systems as a rule of evidence to discredit an entire testimony if part of it is found false, Indian courts have **not adopted it as a mandatory rule**, instead applying the principle of ''separating the chaff from the grain'' to assess credible portions of testimony.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00142', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 67, 'What does ''Cessante Ratione Legis Cessat Ipsa Lex'' mean?', 'This maxim means **''when the reason for a law ceases, the law itself ceases''**. It suggests that a legal rule loses its justification and force once the underlying rationale or purpose for which it was created no longer exists.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00143', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 68, 'What is the meaning of ''Lex Specialis Derogat Legi Generali''?', 'This maxim means **''special law derogates from general law''** — essentially the Latin origin of the principle *generalia specialibus non derogant*. Where a specific statute governs a particular subject, it prevails over a general statute dealing with the same subject matter.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00144', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 69, 'What does ''Omnia Praesumuntur Rite Esse Acta'' mean?', 'This maxim means **''all things are presumed to have been done rightly''**. It embodies a rebuttable presumption of regularity in favour of official and judicial acts, under which courts presume that official acts have been performed correctly unless proven otherwise.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00145', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 70, 'What is the meaning of ''Impotentia Excusat Legem''?', 'This maxim means **''impossibility/inability excuses the law''** or ''the law excuses what is impossible to avoid.'' It is closely related to lex non cogit ad impossibilia, protecting a person from liability where compliance with a legal requirement was genuinely impossible.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00146', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 71, 'What does ''Qui Tacet Consentire Videtur'' mean?', 'This maxim means **''he who is silent is deemed to consent''** (silence implies consent), though it applies only in limited circumstances where a duty to speak existed; mere silence does not generally amount to acceptance or consent under contract law, per the requirement of clear communication of acceptance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00147', 'judiciary-law-bank', 'Legal Reasoning & Maxims', 1, 72, 'What is the significance of the maxim ''Salus Populi Suprema Lex''?', 'This maxim means **''the welfare of the people is the supreme law''**. It is often invoked to justify State action for public welfare, health, and safety, even where it involves some restriction on individual rights, provided such restriction is reasonable and proportionate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00148', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 0, 'What is the definition of ''murder'' under the Indian Penal Code?', '**Murder** is defined under **Section 300 IPC**. Culpable homicide amounts to murder if the act causing death is done with the **intention of causing death**, or with the intention of causing such bodily injury as the offender knows is likely to cause death, or is sufficient in the ordinary course of nature to cause death, or where the person knows the act is so imminently dangerous that it must in all probability cause death, without any excuse.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00149', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 1, 'What is the difference between murder and culpable homicide not amounting to murder?', '**Culpable homicide** (Section 299 IPC) is the genus, and **murder** (Section 300 IPC) is a specific, aggravated species of it.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00150', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 2, 'What are the five exceptions to murder under Section 300 IPC?', 'Section 300 IPC lists five exceptions under which culpable homicide does **not** amount to murder:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00151', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 3, 'What is the punishment for culpable homicide not amounting to murder under Section 304?', '**Section 304 IPC** prescribes imprisonment for life, or imprisonment up to 10 years with fine, if the act is done with the **intention** of causing death or such bodily injury as is likely to cause death; and imprisonment up to 10 years, or fine, or both, if the act is done with the **knowledge** that it is likely to cause death but without such intention.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00152', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 4, 'What is ''Section 304A IPC'' and what does it punish?', '**Section 304A IPC** punishes **death caused by a rash or negligent act** not amounting to culpable homicide, with imprisonment up to **two years**, or fine, or both. It is commonly invoked in cases of fatal road accidents caused by negligent driving.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00153', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 5, 'What is the ingredient and punishment for ''dacoity'' under the IPC?', 'Under **Section 391 IPC**, when **five or more persons** conjointly commit or attempt to commit a robbery, the offence is termed **dacoity**. It is punishable under **Section 395 IPC** with life imprisonment or rigorous imprisonment up to 10 years, along with a fine.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00154', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 6, 'What is the distinction between ''theft'', ''extortion'', and ''robbery''?', '**Theft (Section 378 IPC)** involves dishonestly taking movable property out of another''s possession without consent and without the use of force or fear.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00155', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 7, 'What constitutes ''criminal breach of trust'' under Section 405 IPC?', '**Section 405 IPC** defines **criminal breach of trust** as the dishonest misappropriation or conversion of property entrusted to a person, or dishonest use or disposal of that property in violation of a legal contract or direction, by the person who was entrusted with it. It is punishable under **Section 406 IPC**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00156', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 8, 'What is the distinction between ''cheating'' and ''criminal breach of trust''?', '**Cheating (Section 415 IPC)** involves deceiving a person to dishonestly induce them to deliver property or do/omit an act they would not otherwise have done, causing damage; possession is obtained through deception from the outset.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00157', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 9, 'What are ''general exceptions'' under Chapter IV of the IPC?', '**Chapter IV (Sections 76-106) of the IPC** lays down **general exceptions** which, if established, exempt an accused from criminal liability — including mistake of fact (Sections 76, 79), accident (Section 80), necessity (Section 81), infancy (Sections 82, 83), insanity (Section 84), intoxication (Sections 85, 86), consent (Sections 87-89), and the right of private defence (Sections 96-106).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00158', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 10, 'What does Section 84 IPC (the insanity defence) provide?', '**Section 84 IPC** provides that nothing is an offence if done by a person who, at the time of doing it, by reason of **unsoundness of mind**, is incapable of knowing the **nature of the act**, or that it is **wrong or contrary to law** — reflecting the common law M''Naghten Rules on legal insanity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00159', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 11, 'What is the scope of the right of private defence under Sections 96-106 IPC?', '**Sections 96 to 106 of the IPC** recognise every person''s right to defend their own body and the body of another, as well as property, against an offence affecting the human body, theft, robbery, mischief, or criminal trespass — subject to the limitation that the right does not extend to inflicting **more harm than necessary** for the purpose of defence, and does not apply where there is time to have recourse to public authorities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00160', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 12, 'When does the right of private defence of the body extend to causing death?', 'Under **Section 100 IPC**, the right of private defence of the body extends to voluntarily causing death if the assault reasonably causes apprehension of death, grievous hurt, rape, gratification of unnatural lust, kidnapping/abduction, wrongful confinement under circumstances causing apprehension of inability to have recourse to public authorities, or an act of throwing/administering acid causing reasonable apprehension of grievous hurt.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00161', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 13, 'What is the punishment for ''rape'' under Section 376 IPC?', '**Section 376 IPC** prescribes rigorous imprisonment of not less than **10 years**, which may extend to life imprisonment, along with fine, for the offence of rape as defined under **Section 375 IPC**. Enhanced punishments apply for repeat offenders, gang rape, and rape of minors, with some categories attracting the death penalty following the **Criminal Law (Amendment) Act, 2018**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00162', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 14, 'What amendments were made to rape laws after the Nirbhaya case (2012)?', 'Following the 2012 Delhi gang-rape case, the **Criminal Law (Amendment) Act, 2013**, based on the **Justice J.S. Verma Committee** recommendations, widened the definition of rape under Section 375, introduced new offences such as **acid attack (Section 326A/326B), stalking (Section 354D), and voyeurism (Section 354C)**, and enhanced punishments, including the death penalty for rape causing death or leaving the victim in a persistent vegetative state.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00163', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 15, 'What is the punishment for ''defamation'' under the IPC?', '**Defamation** is defined under **Section 499 IPC** and punishable under **Section 500 IPC** with simple imprisonment up to **two years**, or fine, or both. Its constitutional validity as a criminal offence was upheld by the Supreme Court in *Subramanian Swamy v. Union of India* (2016).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00164', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 16, 'What constitutes ''criminal conspiracy'' under Section 120A IPC?', '**Section 120A IPC** defines **criminal conspiracy** as an agreement between two or more persons to do, or cause to be done, an illegal act, or a legal act by illegal means. Mere agreement is sufficient for conspiracy to do an illegal act; an overt act is required only where the agreement is to do a legal act by illegal means. It is punishable under **Section 120B IPC**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00165', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 17, 'What is the difference between ''abetment'' and ''conspiracy''?', '**Abetment (Sections 107-120 IPC)** involves instigating, engaging in a conspiracy, or intentionally aiding the commission of an offence by another person.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00166', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 18, 'What is the punishment prescribed for ''kidnapping'' under the IPC?', '**Kidnapping** is defined under **Sections 359-361 IPC** (kidnapping from India and kidnapping from lawful guardianship) and is punishable under **Section 363 IPC** with imprisonment up to **seven years**, along with fine. Aggravated forms, such as kidnapping for ransom (Section 364A), attract much higher punishment, including death or life imprisonment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00167', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 19, 'What is the distinction between ''kidnapping'' and ''abduction'' under the IPC?', '**Kidnapping (Sections 359-361 IPC)** is an offence against guardianship, primarily protecting minors (below 16 for males, below 18 for females) and persons of unsound mind, and is complete irrespective of the means used.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00168', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 20, 'What is the ingredient of ''wrongful restraint'' versus ''wrongful confinement'' under the IPC?', '**Wrongful restraint (Section 339 IPC)** is voluntarily obstructing a person so as to prevent them from proceeding in a direction they have a right to proceed, punishable under Section 341 IPC.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00169', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 21, 'What is the definition and punishment of ''grievous hurt'' under the IPC?', '**Section 320 IPC** enumerates eight kinds of injuries classified as **grievous hurt**, including emasculation, permanent loss/impairment of sight or hearing, loss of a limb or joint, permanent disfiguration of the head/face, fracture or dislocation of a bone, and injuries endangering life or causing severe bodily pain/incapacitation for 20 days. Voluntarily causing grievous hurt is punishable under **Section 325 IPC** with imprisonment up to **7 years** and fine.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00170', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 22, 'What is the punishment for ''attempt to murder'' under Section 307 IPC?', '**Section 307 IPC** punishes an **attempt to murder** with imprisonment up to **10 years** along with fine; if hurt is caused to any person by such act, the term may extend to **life imprisonment**. If the act is committed by a person already undergoing a sentence of life imprisonment, it may attract the **death penalty**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00171', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 23, 'What is ''Section 498A IPC'' and what does it address?', '**Section 498A IPC**, inserted by the **Criminal Law (Amendment) Act, 1983**, punishes a husband or his relatives for subjecting a married woman to **cruelty**, which includes wilful conduct likely to drive her to suicide/grave injury, or harassment to coerce her or her relatives to meet unlawful demands for property or valuable security (dowry-related harassment). It is punishable with imprisonment up to **3 years** and fine, and is a cognizable, non-bailable offence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00172', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 24, 'What is the punishment for ''dowry death'' under Section 304B IPC?', '**Section 304B IPC** defines **dowry death** as the death of a woman within **seven years of marriage**, caused by burns, bodily injury, or occurring otherwise than under normal circumstances, where it is shown that she was subjected to cruelty or harassment for dowry soon before her death. It is punishable with a minimum of **seven years**, extending up to life imprisonment, and works alongside the presumption under **Section 113B of the Indian Evidence Act**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00173', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 25, 'What is the ingredient of ''criminal intimidation'' under the IPC?', '**Section 503 IPC** defines **criminal intimidation** as threatening another with injury to their person, reputation, or property (or to a person they are interested in) with intent to cause alarm, or to compel them to do an act they are not legally bound to do, or omit an act they are legally entitled to do. It is punishable under **Section 506 IPC**, with enhanced punishment for threats of death/grievous hurt.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00174', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 26, 'What is the distinction between ''cognizable'' and ''non-cognizable'' offences?', 'In a **cognizable offence**, the police may arrest the accused without a warrant and start investigation without the magistrate''s prior permission (as per the First Schedule of the CrPC/BNSS).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00175', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 27, 'What is the distinction between ''bailable'' and ''non-bailable'' offences?', 'A **bailable offence** is one where bail is a matter of **right**, and the accused is entitled to be released on bail as specified in the First Schedule of the CrPC/BNSS or by any other law.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00176', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 28, 'What is the meaning of ''compoundable'' offences under the CrPC?', '**Compoundable offences**, listed under **Section 320 of the CrPC**, are those where the complainant/victim can agree to withdraw the charges against the accused, resulting in acquittal. Some are compoundable without the court''s permission, others require the court''s permission, while serious offences (like murder) are generally **not compoundable**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00177', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 29, 'What are ''strict liability'' offences, and how are they treated differently from ordinary criminal offences?', '**Strict liability offences** are those where criminal liability can be established upon proof of the **actus reus alone**, without requiring proof of mens rea — commonly seen in regulatory offences such as those under food safety, environmental, and certain licensing statutes, reflecting a deliberate legislative choice to ensure strict compliance in matters of public welfare.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00178', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 30, 'What is the ingredient of ''sedition'' historically under Section 124A IPC?', '**Section 124A IPC** punished bringing or attempting to bring into **hatred or contempt, or exciting disaffection** towards the Government established by law, with imprisonment up to life. In *Kedar Nath Singh v. State of Bihar* (1962), the Supreme Court upheld its validity but read it down to apply only to acts involving incitement to **violence or public disorder**, not mere criticism of the government. The Supreme Court in 2022 ordered its use to be kept in abeyance pending review, and the provision was repealed with the enactment of the Bharatiya Nyaya Sanhita, 2023.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00179', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 31, 'What are the stages of a crime recognised under criminal law?', 'Criminal law recognises four stages in the commission of a crime: **intention**, **preparation**, **attempt**, and **commission**. Generally, mere intention and preparation are not punishable (barring exceptions like preparation to wage war or commit dacoity), while an **attempt** is punishable under provisions such as Section 511 IPC, and the completed act attracts the substantive offence''s punishment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00180', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 32, 'What is the punishment for an attempt to commit an offence under Section 511 IPC?', '**Section 511 IPC** is a residuary provision punishing attempts to commit offences punishable with imprisonment for life or other imprisonment, where no express provision is made for the punishment of such an attempt. It prescribes imprisonment up to **one-half of the longest term** provided for the substantive offence, or with fine, or both.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00181', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 33, 'What is the ingredient and punishment for ''forgery'' under the IPC?', '**Section 463 IPC** defines **forgery** as making a false document or false electronic record, or part of one, with intent to cause damage/injury, to support a claim/title, to cause a person to part with property, or to commit fraud. It is punishable under **Section 465 IPC** with imprisonment up to **two years**, or fine, or both, with enhanced punishment for forgery of valuable security, wills, or for the purpose of cheating.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00182', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 34, 'What is the offence of ''unlawful assembly'' under Section 141 IPC?', '**Section 141 IPC** defines an **unlawful assembly** as an assembly of **five or more persons** with a common object to commit specified acts, such as overawing a public authority by criminal force, resisting execution of law, committing mischief/criminal trespass, or forcibly taking possession of property. Membership of an unlawful assembly is itself punishable under **Section 143 IPC**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00183', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 35, 'What is ''constructive liability'' under Section 149 IPC?', '**Section 149 IPC** provides that if an offence is committed by any member of an unlawful assembly in prosecution of its common object, or one the members knew was likely to be committed, **every member** of that assembly is guilty of that offence, imposing constructive criminal liability on all members regardless of individual participation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00184', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 36, 'What is the ingredient of ''common intention'' under Section 34 IPC?', '**Section 34 IPC** provides that when a criminal act is done by several persons in furtherance of their **common intention**, each is liable for that act as if done by him alone. It requires a **prior meeting of minds** and active participation, and is a rule of evidence/joint liability rather than a substantive offence in itself.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00185', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 37, 'What is the distinction between Section 34 IPC and Section 149 IPC?', '**Section 34 IPC** applies to any number of persons acting with **common intention** and requires active participation by each in furtherance of that shared intention.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00186', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 38, 'What is the ingredient of ''criminal trespass'' under Section 441 IPC?', '**Section 441 IPC** defines **criminal trespass** as entering property in the possession of another with intent to commit an offence, intimidate, insult, or annoy that person, or lawfully entering but then unlawfully remaining with such intent. It is punishable under **Section 447 IPC**, with ''house-trespass'' (Section 442) and ''lurking house-trespass by night'' (Section 443/446) being aggravated variants.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00187', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 39, 'What is the definition and punishment of ''mischief'' under Section 425 IPC?', '**Section 425 IPC** defines **mischief** as causing wrongful loss or damage to public or another''s property by destroying it or diminishing its value/utility, with intent or knowledge that such loss/damage is likely to be caused. It is punishable under **Section 426 IPC** with imprisonment up to **three months**, or fine, or both, with enhanced punishment for mischief causing specific kinds of loss (e.g., destruction of crops, fire, or explosives).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00188', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 40, 'What is the offence of ''voluntarily causing hurt'' under Section 321 and 323 IPC?', '**Section 319 IPC** defines ''hurt'' as causing bodily pain, disease, or infirmity to any person. **Section 321 IPC** defines ''voluntarily causing hurt'' as doing an act with intention or knowledge likely to cause hurt, and such an act is punishable under **Section 323 IPC** with imprisonment up to **one year**, or fine up to one thousand rupees, or both.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00189', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 41, 'What is the offence under Section 302 versus Section 304 Part I and Part II IPC?', '**Section 302 IPC** punishes murder with death or life imprisonment plus fine.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00190', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 42, 'What is the ingredient of ''abetment of suicide'' under Section 306 IPC?', '**Section 306 IPC** punishes the **abetment of suicide**, i.e., instigating, aiding, or engaging in a conspiracy that leads a person to commit suicide, with imprisonment up to **10 years**, along with fine. It requires proof of a clear mens rea and a direct/active act of instigation or incitement, as clarified in several Supreme Court rulings distinguishing mere harassment from active abetment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00191', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 43, 'What is the significance of Section 377 IPC and the Navtej Singh Johar judgment?', '**Section 377 IPC** criminalised ''carnal intercourse against the order of nature.'' In ***Navtej Singh Johar v. Union of India* (2018)**, a five-judge bench of the Supreme Court **decriminalised consensual homosexual acts between adults**, holding that Section 377, to the extent it criminalised consensual same-sex relations, violated Articles 14, 15, 19, and 21 of the Constitution, while retaining the provision for non-consensual acts and bestiality.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00192', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 44, 'What is the ingredient of ''public nuisance'' under Section 268 IPC?', '**Section 268 IPC** defines **public nuisance** as an act or illegal omission causing common injury, danger, or annoyance to the public or people in general who dwell/occupy property in the vicinity, or which necessarily causes injury/obstruction/danger to persons who may have occasion to use a public right. It is punishable under **Section 290 IPC**, typically with a fine.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00193', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 45, 'What is the significance of ''last seen together'' theory in criminal law?', 'The **''last seen together'' theory** is a rule of evidence applied in circumstantial evidence cases, where if the accused was last seen with the deceased shortly before death, and the time gap is so small that the possibility of another person being the author of the crime is excluded, the burden shifts onto the accused under **Section 106 of the Indian Evidence Act** to explain the circumstances, failing which an adverse inference may be drawn.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00194', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 46, 'What are the essential conditions for an offence to be tried under Section 302 read with Section 34 IPC?', 'To convict under **Section 302 read with Section 34 IPC**, the prosecution must prove that the criminal act (murder) was committed by several persons, that it was done in furtherance of a **common intention** shared by all the accused, and that there was participation (physical or otherwise) by each accused in that criminal act pursuant to the shared intention — requiring proof of prior concert, express or tacit.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00195', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 47, 'What is the meaning and ingredients of ''hostile witness'' in criminal trials?', 'A **hostile witness** is a witness who, during examination, gives testimony adverse to the interest of the party who called them, often by resiling from an earlier statement made to the police. Under **Section 154 of the Indian Evidence Act**, the court may permit the party calling such a witness to **cross-examine their own witness** by granting leave, though evidence of a hostile witness is not wholly discarded and may be relied upon to the extent found credible.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00196', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 48, 'What is the ''theory of last-grade evidence'' or the ''golden thread'' principle in criminal jurisprudence?', 'The **''golden thread'' principle**, traced to *Woolmington v. Director of Public Prosecutions* (1935) and consistently followed by Indian courts, holds that the **burden of proving the guilt of the accused beyond reasonable doubt always lies on the prosecution**, and it never shifts to the accused, who is presumed innocent until proven guilty.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00197', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 49, 'What is the significance of ''benefit of doubt'' in criminal law?', 'The principle **''benefit of doubt''** reflects the standard that the prosecution must prove its case **beyond reasonable doubt**; if the evidence creates a genuine, reasonable doubt as to the guilt of the accused, the accused is entitled to be acquitted, since it is considered better that several guilty persons escape than one innocent suffer, per the maxim often attributed to Blackstone.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00198', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 50, 'What is the ingredient of ''Section 420 IPC'' (cheating and dishonestly inducing delivery of property)?', '**Section 420 IPC** punishes a person who cheats and thereby dishonestly induces the person deceived to deliver any property, or to make, alter, or destroy any valuable security, with imprisonment up to **seven years**, along with fine. It is one of the most frequently invoked provisions in financial fraud cases.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00199', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 51, 'What are the categories of punishment prescribed under Section 53 IPC?', '**Section 53 IPC** prescribes five kinds of punishments: **death**, **imprisonment for life**, **imprisonment** (which may be rigorous or simple), **forfeiture of property**, and **fine**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00200', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 52, 'What is the significance of the ''rarest of rare'' doctrine for awarding the death penalty?', 'The **''rarest of rare'' doctrine**, laid down in ***Bachan Singh v. State of Punjab* (1980)**, holds that the death penalty should be imposed only in the ''rarest of rare'' cases where the alternative option of life imprisonment is unquestionably foreclosed, requiring courts to weigh aggravating and mitigating circumstances and consider the possibility of reformation before imposing capital punishment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00201', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 53, 'What is the significance of Bachan Singh v. State of Punjab (1980) for the death penalty in India?', 'In ***Bachan Singh v. State of Punjab* (1980)**, a five-judge bench upheld the constitutional validity of the **death penalty** under Section 302 IPC, holding it does not violate Articles 14, 19, or 21, but confined its application to the ''rarest of rare'' cases, requiring special reasons to be recorded for imposing capital punishment over life imprisonment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00202', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 54, 'What is the ingredient of ''causing miscarriage'' under Section 312 IPC?', '**Section 312 IPC** punishes voluntarily causing a woman with child to **miscarry**, unless done in good faith for the purpose of saving the woman''s life, with imprisonment up to **three years**, or fine, or both; if the woman is ''quick with child'' (i.e., foetal movement has begun), the punishment extends up to **seven years**. This provision operates subject to the exceptions carved out by the Medical Termination of Pregnancy Act, 1971.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00203', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 55, 'What is the offence and punishment for ''acid attack'' under Sections 326A and 326B IPC?', '**Section 326A IPC**, inserted by the Criminal Law (Amendment) Act, 2013, punishes voluntarily causing grievous hurt by use of acid with imprisonment of not less than **10 years**, extending to life imprisonment, along with fine payable to the victim. **Section 326B IPC** punishes voluntarily throwing or attempting to throw acid with intent to cause such injury, with imprisonment between **5 and 7 years**, along with fine.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00204', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 56, 'What is the significance of Section 377 read with marital rape exception under Section 375 IPC?', '**Exception 2 to Section 375 IPC** excludes sexual intercourse by a man with his own wife (not being under 18 years) from the definition of rape, commonly referred to as the **''marital rape exception.''** Its constitutional validity has been challenged before the Supreme Court as violative of Articles 14 and 21, and the issue remains an active area of ongoing litigation and legislative debate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00205', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 57, 'What is the ingredient of ''causing death by negligence'' as distinct from culpable homicide?', '**Section 304A IPC** applies where death is caused by a rash or negligent act **without** the intention or knowledge required for culpable homicide under Section 299 — it covers cases of pure negligence (e.g., medical negligence, accidental deaths from rash driving) and carries a comparatively lighter punishment of up to **two years**'' imprisonment, reflecting the absence of a culpable mental state directed towards causing death.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00206', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 58, 'What is the meaning of ''absolute liability'' as evolved in Indian tort/criminal-adjacent jurisprudence, and how does it differ from strict liability?', 'The **rule of absolute liability**, laid down in ***M.C. Mehta v. Union of India* (1987)** (the Oleum Gas Leak case), holds that an enterprise engaged in a hazardous or inherently dangerous activity owes an **absolute and non-delegable duty** to the community, and is liable for any harm resulting from such activity **without any exceptions** (unlike strict liability under *Rylands v. Fletcher*, which permits defences like an act of a stranger or act of God).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00207', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 59, 'What is the ingredient of ''sections dealing with offences against the State'' under Chapter VI IPC?', '**Chapter VI of the IPC (Sections 121-130)** deals with offences against the State, including **waging war against the Government of India (Section 121)**, which is punishable with death or life imprisonment, conspiracy to wage war (Section 121A), and collecting arms with intention of waging war (Section 122).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00208', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 60, 'What is the punishment for ''robbery'' under Section 392 IPC?', '**Section 392 IPC** punishes robbery with rigorous imprisonment up to **10 years**, along with fine; if the robbery is committed on a highway between sunset and sunrise, the imprisonment may extend to **14 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00209', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 61, 'What is the offence of ''assault'' or ''criminal force'' under Sections 350 and 351 IPC?', '**Section 350 IPC** defines **criminal force** as the intentional use of force to another without consent, to commit an offence or with intent/knowledge to cause injury, fear, or annoyance.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00210', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 62, 'What is the significance of Section 125 of the CrPC (now relevant under BNSS) concerning maintenance?', '**Section 125 of the CrPC** (continued as Section 144 of the Bharatiya Nagarik Suraksha Sanhita, 2023) provides a **summary, secular remedy** for maintenance of a wife, children, or parents unable to maintain themselves, irrespective of the personal law governing the parties, aimed at preventing vagrancy and destitution — as reaffirmed by the Supreme Court in *Mohd. Ahmed Khan v. Shah Bano Begum* (1985).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00211', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 63, 'What is the ingredient of ''causing disappearance of evidence'' under Section 201 IPC?', '**Section 201 IPC** punishes a person who, knowing or having reason to believe that an offence has been committed, causes evidence of that offence to disappear with the intention of screening the offender from legal punishment, or gives false information regarding it. The punishment varies depending on the gravity of the principal offence, extending up to **7 years** where the offence is punishable with death.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00212', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 64, 'What is the ingredient of ''giving false evidence'' and ''fabricating false evidence'' under the IPC?', '**Section 191 IPC** defines **giving false evidence** as making a false statement while bound by law to state the truth. **Section 192 IPC** defines **fabricating false evidence** as causing a false circumstance to exist with intent that it appear in evidence. Both are punishable under **Section 193 IPC**, with imprisonment up to **7 years** for fabricating/giving false evidence in a judicial proceeding.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00213', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 65, 'What is the ingredient of ''causing grievous hurt by dangerous weapons'' under Section 326 IPC?', '**Section 326 IPC** punishes voluntarily causing grievous hurt by means of any instrument for shooting, stabbing, or cutting, or any instrument likely to cause death, or by fire, heated substance, poison, or corrosive substance, with imprisonment up to **life imprisonment** or up to **10 years**, along with fine.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00214', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 66, 'What is the ingredient of the offence of ''house-breaking'' under the IPC?', '**Section 445 IPC** defines **house-breaking** as committing house-trespass through specified means of entry/exit (such as passing through a passage made by the offender, scaling/climbing an enclosure, or unfastening a lock), and it is treated as an aggravated form of house-trespass, punishable more severely than simple trespass, particularly when committed by night (Section 446 IPC).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00215', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 67, 'What is the ingredient of ''Section 304B'' presumption as to dowry death, read with Section 113B of the Evidence Act?', '**Section 113B of the Indian Evidence Act** raises a statutory **presumption** that, once it is shown a woman was subjected to cruelty/harassment for dowry ''soon before her death'' and died an unnatural death within seven years of marriage, the court **shall presume** that the accused caused the dowry death under Section 304B IPC, shifting the burden onto the accused to rebut this presumption.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00216', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 68, 'What is the distinction between ''simple imprisonment'' and ''rigorous imprisonment'' under the IPC?', '**Simple imprisonment** confines a convict without any obligation to perform hard labour, whereas **rigorous imprisonment** requires the convict to perform **hard labour** during the term of imprisonment, as specified under **Section 53 IPC**. Courts may prescribe either form depending on the specific statutory provision.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00217', 'judiciary-law-bank', 'Indian Penal Code / Criminal Law Basics', 2, 69, 'What is the ingredient of ''attempt to commit suicide'' and its decriminalisation history?', '**Section 309 IPC** historically punished attempt to commit suicide with simple imprisonment up to **one year**, or fine, or both. The **Mental Healthcare Act, 2017** (Section 115) effectively decriminalised attempted suicide by presuming that a person attempting suicide is under severe stress and should not be tried or punished under Section 309 unless proved otherwise, and the provision has been omitted in the Bharatiya Nyaya Sanhita, 2023.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00218', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 0, 'What is the definition of ''contract'' under Section 2(h) of the Indian Contract Act, 1872?', '**Section 2(h)** of the **Indian Contract Act, 1872** defines a **contract** as **''an agreement enforceable by law.''** It thus requires two elements: an **agreement** (offer plus acceptance) and **enforceability** at law, meaning the agreement must satisfy the conditions laid down in Section 10 of the Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00219', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 1, 'What are the essential elements of a valid contract under Section 10?', '**Section 10** of the Indian Contract Act provides that an agreement is a contract if made by parties **competent to contract**, with their **free consent**, for a **lawful consideration** and **lawful object**, and is **not expressly declared void** under the Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00220', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 2, 'What is the difference between ''offer'' and ''invitation to offer''?', 'An **offer (proposal)**, defined under **Section 2(a)**, is a final expression of willingness to be bound on acceptance without further negotiation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00221', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 3, 'What is ''consideration'' under Section 2(d) of the Contract Act?', '**Section 2(d)** defines **consideration** as something done, or an abstinence/promise made, at the desire of the promisor by the promisee or any other person, which may be past, present, or future.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00222', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 4, 'What is the rule ''no consideration, no contract'' and its exceptions under Section 25?', 'The general rule is that **an agreement without consideration is void** (Section 25). However, **Section 25** carves out exceptions where such an agreement is still valid: agreements made out of **natural love and affection** between parties in a near relation (in writing and registered), a promise to compensate for a **past voluntary act**, and a promise to pay a **time-barred debt** in writing signed by the debtor.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00223', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 5, 'What is the difference between ''void'' and ''voidable'' contracts?', 'A **void contract** (Section 2(j)) is one that ceases to be enforceable by law, having no legal effect from the point it becomes void — it cannot be ratified.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00224', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 6, 'Who is considered ''competent to contract'' under Section 11?', '**Section 11** provides that every person is competent to contract who is of the **age of majority**, of **sound mind**, and **not disqualified** from contracting by any law to which they are subject (e.g., an alien enemy, insolvent, or convict).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00225', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 7, 'What is the legal position of an agreement with a minor, as per Mohori Bibee v. Dharmodas Ghose (1903)?', 'In ***Mohori Bibee v. Dharmodas Ghose* (1903)**, the Privy Council held that an **agreement with a minor is void ab initio** (void from the outset), not merely voidable, since a minor is not competent to contract under Section 11; consequently, there can be no question of ratification on attaining majority, and the doctrine of estoppel does not apply against a minor.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00226', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 8, 'What constitutes ''free consent'' under Section 14 of the Contract Act?', '**Section 14** states that consent is **''free''** when it is not caused by **coercion (Section 15)**, **undue influence (Section 16)**, **fraud (Section 17)**, **misrepresentation (Section 18)**, or **mistake (Sections 20-22)**. If consent is caused by the first four factors, the contract is generally voidable; mistake of fact by both parties renders the agreement void.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00227', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 9, 'What is the difference between ''fraud'' and ''misrepresentation'' under Sections 17 and 18?', '**Fraud (Section 17)** involves a false representation made **knowingly, without belief in its truth, or recklessly**, with intent to deceive and induce a party to enter a contract.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00228', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 10, 'What is ''undue influence'' under Section 16 of the Contract Act?', '**Section 16** defines **undue influence** as a situation where one party, being in a position to **dominate the will** of the other (due to a real/apparent authority, a fiduciary relationship, or the other''s mental/physical distress), uses that position to obtain an unfair advantage over the other.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00229', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 11, 'What is the effect of ''mistake of fact'' under Sections 20-22 of the Contract Act?', 'Under **Section 20**, where **both parties** are under a mistake as to a matter of fact **essential** to the agreement, the agreement is **void**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00230', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 12, 'What agreements are expressly declared void under the Contract Act?', 'The Contract Act expressly declares several categories of agreements void, including: agreements without consideration (Section 25) subject to exceptions, agreements **in restraint of marriage** (Section 26), agreements **in restraint of trade** (Section 27), agreements **in restraint of legal proceedings** (Section 28), agreements that are **uncertain** in meaning (Section 29), and **wagering agreements** (Section 30).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00231', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 13, 'What is the exception regarding sale of goodwill under Section 27 (restraint of trade)?', '**Section 27** declares every agreement restraining a person from exercising a lawful profession, trade, or business void, **except** that a buyer of **goodwill** of a business may validly impose reasonable restrictions on the seller as to carrying on a similar business within specified local limits, so long as such limits appear reasonable to the court having regard to the nature of the business.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00232', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 14, 'What is a ''wagering agreement'' under Section 30, and is it void or illegal?', '**Section 30** declares **wagering agreements** (bets on an uncertain future event where neither party has any other interest in the outcome) to be **void**, not illegal — meaning collateral transactions connected with a wager are not automatically tainted, unlike agreements that are illegal, which also void any connected collateral transaction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00233', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 15, 'What is the meaning of ''quasi-contract'' under Chapter V of the Contract Act?', '**Chapter V (Sections 68-72)** of the Contract Act deals with **''certain relations resembling those created by contract''**, commonly termed quasi-contracts — obligations imposed by law, independent of any actual agreement, to prevent unjust enrichment, such as a claim for necessaries supplied to a person incapable of contracting (Section 68) or for a sum paid under mistake or coercion (Section 72).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00234', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 16, 'What is ''anticipatory breach'' of contract?', '**Anticipatory breach** occurs when a party, before the time fixed for performance arrives, either expressly renounces the contract or does an act making future performance impossible. The aggrieved party may immediately treat the contract as discharged and sue for damages, or wait until the actual date of performance, as recognised under **Section 39** of the Contract Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00235', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 17, 'What remedies are available for breach of contract under Indian law?', 'Remedies for breach of contract include **damages** (Sections 73-75), **specific performance** (under the Specific Relief Act, 1963), **injunction**, **rescission** of the contract, and **restitution/quantum meruit** (payment for value of work already done).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00236', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 18, 'What is the rule in Hadley v. Baxendale (1854) regarding damages?', '***Hadley v. Baxendale* (1854)** laid down the rule that damages recoverable for breach of contract are those arising **naturally from the breach**, in the usual course of things, or those which both parties knew, at the time of contracting, were likely to result from the breach — special/remote damages are recoverable only if the special circumstances were communicated at the time of contracting. This principle underlies **Section 73** of the Indian Contract Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00237', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 19, 'What is the doctrine of ''frustration of contract'' under Section 56?', '**Section 56** of the Contract Act embodies the **doctrine of frustration**, providing that an agreement to do an act that becomes **impossible**, or by reason of some subsequent event the promisor could not prevent becomes unlawful, becomes **void** when the act becomes impossible or unlawful, discharging both parties from further performance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00238', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 20, 'What is the distinction between ''contingent contract'' and ''wagering agreement''?', 'A **contingent contract (Section 31)** is one to do or not do something if some event, collateral to the contract, does or does not happen, and is enforceable provided the contingency occurs (e.g., insurance contracts).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00239', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 21, 'What is ''quantum meruit''?', '**Quantum Meruit** means **''as much as earned/merited''**. It is an equitable remedy allowing a party to claim reasonable remuneration for work done or services rendered when a contract is discharged (e.g., by breach by the other party, or because it is found void) before complete performance, preventing unjust enrichment of the other party.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00240', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 22, 'What is the ''doctrine of privity of contract''?', 'The **doctrine of privity of contract** holds that only parties to a contract can sue or be sued on it; a stranger to the contract cannot enforce its terms even if the contract was made for their benefit, as held in the English case *Tweddle v. Atkinson* (1861). Indian law recognises certain **exceptions**, such as trusts, family settlements, and acknowledgment creating an agency, as seen in *M.C. Chacko v. State Bank of Travancore* (1970).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00241', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 23, 'What is ''novation'', ''rescission'', and ''alteration'' under Section 62 of the Contract Act?', '**Section 62** provides that if the parties to a contract agree to **substitute a new contract** for the old one (**novation**), or to **rescind** (cancel) it, or to **alter** its terms, the original contract need not be performed. All three require mutual consent of the parties and discharge the original obligations to the extent of the change agreed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00242', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 24, 'What is the meaning of ''tort'' and how does it differ from a breach of contract?', 'A **tort** is a civil wrong, independent of contract, for which the remedy is an action for **unliquidated damages**, arising from a breach of a duty fixed by **law** (owed to persons generally), not by agreement between parties.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00243', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 25, 'What are the essential elements of the tort of negligence?', 'The tort of **negligence** requires proof of: (i) a **duty of care** owed by the defendant to the plaintiff, (ii) **breach** of that duty by falling below the standard of a reasonable person, (iii) **causation** — the breach caused the damage, and (iv) **damage** suffered by the plaintiff that was not too remote.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00244', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 26, 'What is the ''neighbour principle'' from Donoghue v. Stevenson (1932)?', 'In ***Donoghue v. Stevenson* (1932)**, Lord Atkin laid down the **''neighbour principle''**, holding that a person must take reasonable care to avoid acts or omissions which they can reasonably foresee would be likely to injure their ''neighbour'' — persons so closely and directly affected by the act that they ought reasonably to be in contemplation as being so affected. This case established the modern foundation of the **duty of care** in negligence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00245', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 27, 'What is the rule in Rylands v. Fletcher (1868) on strict liability?', '***Rylands v. Fletcher* (1868)** established the rule of **strict liability**: a person who, for their own purposes, brings onto their land and keeps anything likely to do mischief if it escapes, must keep it at their peril, and is liable for all damage that results from its escape, even without negligence — subject to defences such as act of God, act of a stranger, plaintiff''s own default, and statutory authority.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00246', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 28, 'How does the rule of ''absolute liability'' from M.C. Mehta v. Union of India (1987) differ from the rule in Rylands v. Fletcher?', 'The rule of **absolute liability**, evolved in ***M.C. Mehta v. Union of India* (1987)** for enterprises engaged in hazardous or inherently dangerous activities, imposes liability **without any of the exceptions** available under Rylands v. Fletcher (such as act of a stranger, act of God, or plaintiff''s consent), making it a more stringent standard suited to Indian conditions involving hazardous industries.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00247', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 29, 'What is ''vicarious liability'' in tort law?', '**Vicarious liability** refers to the liability of one person for the tort committed by another, based on a specific legal relationship between them — most commonly an **employer''s liability** for torts committed by an employee acting within the **course of employment**, grounded in the maxims qui facit per alium facit per se and respondeat superior.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00248', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 30, 'What is the defence of ''volenti non fit injuria'' in tort law, and what are its limitations?', '**Volenti non fit injuria** means that a person who voluntarily consents to or assumes a known risk cannot complain of resulting injury. It does not apply where consent was obtained by **fraud**, where the act is **illegal**, or in cases of **rescue**, where a rescuer''s voluntary assumption of risk to save another does not bar their claim, as established in *Haynes v. Harwood* (1935).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00249', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 31, 'What is the defence of ''contributory negligence'' in tort law?', '**Contributory negligence** is a defence where the plaintiff''s own lack of reasonable care contributed to the harm suffered. Under Indian law (and many jurisdictions following comparative negligence statutes), damages are typically **apportioned** between the parties based on their relative degree of fault, rather than completely barring the plaintiff''s claim.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00250', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 32, 'What is ''defamation'' as a tort, and what are its two forms?', '**Defamation** is the publication of a false statement that injures the reputation of another. It takes two forms: **libel** (defamation in a permanent, visible form, such as writing or print) and **slander** (defamation in a transient form, such as spoken words or gestures). Libel is generally actionable per se, while slander, barring certain exceptions, usually requires proof of actual/special damage.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00251', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 33, 'What defences are available to a defendant in a defamation action?', 'Defences to a defamation claim include **justification/truth** (the statement was substantially true), **fair comment** (an honest opinion on a matter of public interest based on true facts), and **privilege** — either **absolute privilege** (e.g., statements made in Parliament or judicial proceedings) or **qualified privilege** (statements made in good faith in discharge of a legal, moral, or social duty).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00252', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 34, 'What is the tort of ''nuisance'', and what is the distinction between public and private nuisance?', '**Nuisance** is an unlawful interference with a person''s use or enjoyment of land, or of some right connected with it.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00253', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 35, 'What is the tort of ''trespass to land''?', '**Trespass to land** is the direct and unjustifiable interference with the possession of land in the possession of another, whether by entering upon it, remaining on it after permission has been withdrawn, or placing/throwing an object upon it. It is actionable **per se**, without proof of actual damage, since it is a violation of a possessory right.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00254', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 36, 'What is ''false imprisonment'' as a tort?', '**False imprisonment** is the total restraint of a person''s liberty, without lawful justification, for any period of time, however short — even without actual physical force, so long as the person is unable to exercise their freedom of movement in all directions. It is actionable per se, and the plaintiff need not prove awareness of the restraint at the time, per *Bird v. Jones* (1845) and Meering v. Grahame-White Aviation Co. (1919).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00255', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 37, 'What is the doctrine of ''remoteness of damage'' in tort law?', 'The **doctrine of remoteness of damage** limits a defendant''s liability to consequences that are not too remote from the wrongful act. The modern test, from ***The Wagon Mound (No. 1)* (1961)**, is whether the **kind of damage** suffered was **reasonably foreseeable** as a consequence of the defendant''s act, replacing the older ''direct consequence'' test from *Re Polemis* (1921).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00256', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 38, 'What is ''malicious prosecution'' as a tort?', '**Malicious prosecution** is a tort where the defendant sets the criminal law in motion against the plaintiff **maliciously** and **without reasonable and probable cause**, and the prosecution ends in the plaintiff''s favour (acquittal/discharge), resulting in damage to reputation, person, or property. All four elements — prosecution, favourable termination, absence of reasonable cause, and malice — must be established.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00257', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 39, 'What are ''general'', ''special'', ''nominal'', and ''exemplary'' damages in tort law?', '**General damages** are those presumed by law to naturally flow from the wrong and need not be specifically pleaded or proved (e.g., pain and suffering).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00258', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 40, 'What is the meaning and scope of the Specific Relief Act, 1963?', 'The **Specific Relief Act, 1963** provides equitable remedies in addition to the common law remedy of damages, including **specific performance** of contracts, **injunctions** (temporary/permanent, prohibitory/mandatory), **rescission** and **cancellation** of instruments, **declaratory decrees**, and recovery of possession of **property**. The Act was substantially amended in **2018** to make specific performance a more general remedy rather than a purely discretionary one.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00259', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 41, 'How did the 2018 amendment to the Specific Relief Act change the approach to specific performance?', 'Before the **2018 amendment**, specific performance was a **discretionary** remedy, granted only when damages were inadequate. The amendment substituted Section 10 to make specific performance the rule rather than the exception — courts must now generally grant specific performance of a contract, subject only to specified exceptions under Sections 14 and 16, reducing the earlier wide judicial discretion.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00260', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 42, 'What is the distinction between ''indemnity'' and ''guarantee'' contracts under Sections 124 and 126?', 'A **contract of indemnity (Section 124)** involves one party promising to save the other from loss caused by the conduct of the promisor or any other person — it involves **two parties**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00261', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 43, 'What are the rights of a surety under the Indian Contract Act?', 'A **surety** has, upon payment of the guaranteed debt, the right of **subrogation** (stepping into the shoes of the creditor against the principal debtor under Section 140), the right to be **indemnified** by the principal debtor (Section 145), and is **discharged from liability** in certain situations, such as a variance in contract terms without the surety''s consent (Section 133), or release/discharge of the principal debtor by the creditor (Section 134).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00262', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 44, 'What is a ''contract of bailment'' under Section 148 of the Contract Act?', '**Section 148** defines **bailment** as the delivery of goods by one person (**bailor**) to another (**bailee**) for some purpose, upon a contract that the goods shall, when the purpose is accomplished, be returned or otherwise disposed of according to the bailor''s directions. The bailee owes a duty of reasonable care under **Section 151**, the standard of which varies with the nature of the bailment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00263', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 45, 'What is a ''contract of pledge'' and how does it differ from bailment generally?', 'A **pledge (Section 172)** is a special kind of bailment where goods are delivered as **security for payment of a debt or performance of a promise**. The pledgor is called the **pawnor** and the pledgee the **pawnee**. Unlike general bailment, a pledge specifically secures an obligation, and the pawnee has a right to retain the goods until the debt is discharged, along with a limited right of sale upon default (Section 176).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00264', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 46, 'What is a ''contract of agency'' under Section 182 of the Contract Act?', '**Section 182** defines an **''agent''** as a person employed to do any act for another, or to represent another in dealings with third persons, and the person for whom such act is done is called the **''principal.''** An agency may be created expressly, impliedly, by ratification, or by necessity, and the principal is generally bound by the acts of the agent done within the scope of their authority.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00265', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 47, 'What is the principle of ''unjust enrichment'' and how is it addressed under Indian contract law?', '**Unjust enrichment** refers to a situation where one party is unfairly enriched at the expense of another without legal justification. Indian law addresses it primarily through the quasi-contractual provisions in **Chapter V (Sections 68-72)** of the Contract Act, which impose an obligation to compensate or restore benefits received, even in the absence of a formal contract, to prevent one party from being unjustly enriched.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00266', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 48, 'What is the meaning of ''liquidated damages'' and ''penalty'' under Section 74 of the Contract Act?', '**Section 74** provides that when a contract names a sum to be paid in case of breach (as **liquidated damages** or as a **penalty**), the party complaining of breach is entitled to receive reasonable compensation not exceeding the amount named, **regardless of whether actual loss or damage is proved** — Indian law does not distinguish between a genuine pre-estimate of damages and a penalty the way English law does, and compensation is capped at the named sum.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00267', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 49, 'What is the significance of the case Satyabrata Ghose v. Mugneeram Bangur & Co. (1954) for the doctrine of frustration?', 'In ***Satyabrata Ghose v. Mugneeram Bangur & Co.* (1954)**, the Supreme Court clarified that the doctrine of frustration under **Section 56** of the Contract Act is not based on an implied term theory (as in English law) but is a **positive rule of Indian law**, applying whenever performance becomes impossible or the very foundation of the contract is destroyed by a supervening event beyond the parties'' control.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00268', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 50, 'What is the rule relating to acceptance of a contract by post, i.e., the ''postal rule''?', 'Under the general postal rule (reflected in **Sections 4 and 5** of the Contract Act), an **acceptance** is complete as against the proposer when it is **put into the course of transmission** (posted), but as against the acceptor, only when it comes to the knowledge of the proposer — meaning the proposer cannot revoke after posting of acceptance, but the acceptor can revoke their acceptance before it reaches the proposer.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00269', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 51, 'What is the meaning of ''implied conditions and warranties'' under the Sale of Goods Act, 1930?', 'The **Sale of Goods Act, 1930** implies certain conditions and warranties into a contract of sale unless excluded, such as the **condition as to title** (Section 14), **condition as to merchantable quality** and **fitness for purpose** (Section 16), and the **implied warranty of quiet possession** — a breach of a condition entitles the buyer to repudiate the contract, while a breach of warranty only entitles the buyer to claim damages.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00270', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 52, 'What is the distinction between a ''condition'' and a ''warranty'' in a contract of sale?', 'A **condition** is a stipulation **essential** to the main purpose of the contract, the breach of which gives the aggrieved party the right to treat the contract as **repudiated**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00271', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 53, 'What is the meaning of ''coercion'' under Section 15 of the Contract Act?', '**Section 15** defines **coercion** as committing or threatening to commit any act forbidden by the Indian Penal Code, or the unlawful detaining or threatening to detain any property, with the intention of causing a person to enter into an agreement. A contract caused by coercion is **voidable** at the option of the party whose consent was so obtained.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00272', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 54, 'What is the distinction between an ''agreement'' and a ''contract''?', 'An **agreement** (Section 2(e)) is every promise and every set of reciprocal promises forming consideration for each other.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00273', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 55, 'What is the effect of an agreement with an unlawful object or consideration under Section 23?', '**Section 23** provides that the consideration or object of an agreement is unlawful if it is forbidden by law, is of such a nature that it would defeat the provisions of any law, is fraudulent, involves injury to person/property, or is regarded as immoral or opposed to public policy. Any agreement whose object or consideration is unlawful is **void**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00274', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 56, 'What is meant by ''performance of reciprocal promises'' under Sections 51-54 of the Contract Act?', '**Sections 51-54** govern **reciprocal promises**, i.e., promises forming consideration for each other. They provide rules for situations where promises are to be simultaneously performed, where the order of performance is expressly or impliedly fixed, and the consequences where one party prevents the other from performing their reciprocal promise.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00275', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 57, 'What is the meaning of ''time is of the essence'' in a contract?', 'The phrase **''time is of the essence''** means that performance within the stipulated time is a vital term of the contract, and failure to perform within time entitles the aggrieved party to avoid the contract. Under **Section 55** of the Contract Act, whether time is of the essence depends on the intention of the parties and the nature of the contract — in commercial contracts, it is often presumed to be essential, while in contracts relating to immovable property, courts are generally reluctant to treat it as essential unless expressly stipulated.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00276', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 58, 'What is a ''standard form contract'' and how do Indian courts regulate unfair terms in it?', 'A **standard form contract** is one where one party (usually with greater bargaining power, such as an insurer or service provider) drafts the terms on a take-it-or-leave-it basis, leaving the other party with little or no opportunity to negotiate. Indian courts have used doctrines like reasonableness, fairness, and public policy, together with specific consumer-protection legislation, to strike down or read down **unconscionable or oppressive terms** in such contracts, as seen in *Central Inland Water Transport Corp. v. Brojo Nath Ganguly* (1986).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00277', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 59, 'What is the tort of ''conversion''?', '**Conversion** is an intentional tort involving dealing with the goods of another in a manner inconsistent with the owner''s right of possession, such as wrongfully taking, using, selling, or destroying another''s property, thereby denying the owner''s title. It is actionable regardless of the defendant''s good faith belief in their own entitlement.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00278', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 60, 'What is the tort of ''passing off''?', '**Passing off** is a common law tort (also protected under the Trade Marks Act, 1999) that prevents a trader from misrepresenting their goods or services as those of another, thereby causing damage to the goodwill of the genuine trader. It protects unregistered marks and reputation, unlike a straightforward trademark infringement action which requires a registered mark.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00279', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 61, 'What is the ''eggshell skull rule'' in tort law?', 'The **''eggshell skull rule''** (or ''thin skull rule'') provides that a defendant must take their victim as they find them — if the plaintiff has a pre-existing vulnerability or condition that makes the injury more severe than it would be for an ordinary person, the defendant is still liable for the **full extent** of the damage actually caused, and cannot argue that the harm was unforeseeable merely because of the plaintiff''s unusual susceptibility.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00280', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 62, 'What is the distinction between ''joint tortfeasors'' and ''several/independent tortfeasors''?', '**Joint tortfeasors** are persons who act in concert pursuant to a common design to commit a tort, making them jointly and severally liable for the entire damage.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00281', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 63, 'What is the meaning of ''injunction'' as an equitable remedy, and what are its types?', 'An **injunction** is a judicial order restraining a person from doing, or commanding them to do, a particular act, governed by the **Specific Relief Act, 1963**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00282', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 64, 'What is the doctrine of ''promissory estoppel'' in Indian contract law?', 'The **doctrine of promissory estoppel** prevents a party from going back on a clear and unequivocal promise, which was intended to create legal relations and was acted upon by the other party to their detriment, even in the absence of formal consideration. Indian courts have applied it extensively against the **Government and public authorities**, as seen in *Union of India v. Anglo Afghan Agencies* (1968) and *Motilal Padampat Sugar Mills v. State of U.P.* (1979), subject to the public interest exception.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00283', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 65, 'What are the grounds on which a contract may be discharged, apart from performance and breach?', 'Besides discharge by **performance** and **breach**, a contract may be discharged by **mutual agreement** (novation, rescission, alteration, or remission under Sections 62-63), by **impossibility/frustration of performance** (Section 56), by **lapse of time** (under the Limitation Act, 1963), and by **operation of law** (e.g., merger, insolvency, or death in contracts of a personal nature).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00284', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 66, 'What is the significance of Carlill v. Carbolic Smoke Ball Co. (1893) for the law of offer and acceptance?', 'In ***Carlill v. Carbolic Smoke Ball Co.* (1893)**, the court held that a general advertisement offering a reward to anyone who performed specified conditions constituted a valid **unilateral offer** to the whole world, capable of acceptance by performance of the stipulated conditions without need for communication of acceptance in advance, and that the deposit of money in a bank showed genuine intention to be bound, satisfying the requirement of consideration.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00285', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 67, 'What is the meaning of ''remission and waiver'' under Section 63 of the Contract Act?', '**Section 63** allows a promisee to **dispense with or remit**, wholly or in part, the performance of a promise made to them, or to extend the time for performance, or accept any satisfaction they think fit instead of actual performance — without any fresh consideration being required for such remission or waiver.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00286', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 68, 'What is meant by the ''duty to mitigate damages'' in contract and tort law?', 'The **duty to mitigate** requires a claimant, upon a breach of contract or commission of a tort, to take all **reasonable steps** to minimise the loss suffered, and they cannot claim compensation for any part of the loss that is due to their own neglect to take such reasonable steps — it is not a positive duty owed to the defendant, but a limitation on the damages that can be recovered.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00287', 'judiciary-law-bank', 'Law of Contracts & Torts', 3, 69, 'What is the tort of ''negligent misstatement'' as recognised in Hedley Byrne & Co. v. Heller & Partners (1964)?', 'In ***Hedley Byrne & Co. v. Heller & Partners* (1964)**, the House of Lords recognised that a **negligent misstatement** causing purely financial (economic) loss can give rise to liability in tort, where there exists a **''special relationship''** between the parties involving an assumption of responsibility by the person giving advice/information and reasonable reliance by the recipient — extending the tort of negligence beyond physical injury to pure economic loss in specific circumstances.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00288', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 0, 'What was decided in Kesavananda Bharati v. State of Kerala (1973)?', '***Kesavananda Bharati v. State of Kerala* (1973)**, decided by a **13-judge bench** (the largest ever in Indian history), held by a narrow 7-6 majority that Parliament''s power to amend the Constitution under **Article 368** is wide but does not extend to altering or destroying its **''basic structure''** — establishing the **basic structure doctrine** as a permanent limitation on the amending power.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00289', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 1, 'What was decided in Maneka Gandhi v. Union of India (1978)?', 'In ***Maneka Gandhi v. Union of India* (1978)**, the Supreme Court held that the **''procedure established by law''** under Article 21 must be **fair, just, and reasonable**, not arbitrary or oppressive, and that Articles 14, 19, and 21 are not mutually exclusive but form an interconnected ''golden triangle'' — greatly expanding the scope of personal liberty and reading substantive due process into Article 21.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00290', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 2, 'What was the significance of A.K. Gopalan v. State of Madras (1950)?', 'In ***A.K. Gopalan v. State of Madras* (1950)**, the Supreme Court initially adopted a **narrow, literal interpretation** of Article 21, holding that ''procedure established by law'' only required a procedure to be validly enacted, without necessarily being fair or reasonable, and that Fundamental Rights operated in **separate, water-tight compartments**. This restrictive view was later overturned by *Maneka Gandhi v. Union of India* (1978).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00291', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 3, 'What was decided in Golaknath v. State of Punjab (1967)?', 'In ***I.C. Golaknath v. State of Punjab* (1967)**, the Supreme Court held, by a 6-5 majority, that Parliament had **no power to amend Part III (Fundamental Rights)** of the Constitution, treating a constitutional amendment under Article 368 as ''law'' within the meaning of Article 13(2). This position was subsequently overruled in *Kesavananda Bharati* (1973), which permitted amendment of Fundamental Rights subject to the basic structure doctrine.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00292', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 4, 'What was decided in Minerva Mills Ltd. v. Union of India (1980)?', 'In ***Minerva Mills Ltd. v. Union of India* (1980)**, the Supreme Court struck down clauses of the **42nd Amendment** that gave Directive Principles (Part IV) unconditional primacy over Fundamental Rights (Part III) and removed limits on Parliament''s amending power, holding that a **limited amending power** and the **harmony/balance between Parts III and IV** are themselves part of the basic structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00293', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 5, 'What was decided in S.R. Bommai v. Union of India (1994)?', '***S.R. Bommai v. Union of India* (1994)** laid down guidelines curbing the misuse of **Article 356** (President''s Rule), holding that the proclamation is subject to **judicial review**, a **floor test** in the legislature is the true test of majority, and that **secularism** is part of the Constitution''s basic structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00294', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 6, 'What was decided in Indra Sawhney v. Union of India (1992), the Mandal Commission case?', 'In ***Indra Sawhney v. Union of India* (1992)**, a nine-judge bench upheld **27% reservation** for Other Backward Classes (OBCs) in central government jobs, introduced the **''creamy layer''** exclusion concept, held that total reservations should **not ordinarily exceed 50%**, and ruled that reservation should generally be limited to initial appointments, not promotions (though this was later altered by constitutional amendment for SC/ST).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00295', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 7, 'What was decided in Vishaka v. State of Rajasthan (1997)?', 'In ***Vishaka v. State of Rajasthan* (1997)**, the Supreme Court, invoking international conventions in the absence of domestic legislation, laid down binding guidelines (the **''Vishaka Guidelines''**) to prevent and redress **sexual harassment of women at the workplace**, which remained in force until Parliament enacted the **Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00296', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 8, 'What was decided in Olga Tellis v. Bombay Municipal Corporation (1985)?', 'In ***Olga Tellis v. Bombay Municipal Corporation* (1985)**, the Supreme Court held that the **right to livelihood** is an integral facet of the **right to life** under Article 21, since no person can live without the means of livelihood, though it also held that eviction of pavement dwellers could be carried out if a fair, just, and reasonable procedure was followed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00297', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 9, 'What was decided in M.C. Mehta v. Union of India (1987), the Oleum Gas Leak case?', 'In ***M.C. Mehta v. Union of India* (1987)**, arising from an oleum gas leak in Delhi, the Supreme Court evolved the rule of **''absolute liability''** for enterprises engaged in hazardous or inherently dangerous activities, holding them liable for any resulting harm without the defences available under the English rule in *Rylands v. Fletcher*.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00298', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 10, 'What was decided in Shah Bano Begum case, Mohd. Ahmed Khan v. Shah Bano Begum (1985)?', 'In ***Mohd. Ahmed Khan v. Shah Bano Begum* (1985)**, the Supreme Court held that a divorced Muslim woman unable to maintain herself is entitled to maintenance from her former husband under the secular provision of **Section 125 of the Code of Criminal Procedure**, irrespective of personal law — a ruling that led to significant political controversy and the subsequent enactment of the Muslim Women (Protection of Rights on Divorce) Act, 1986.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00299', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 11, 'What was decided in Shreya Singhal v. Union of India (2015)?', 'In ***Shreya Singhal v. Union of India* (2015)**, the Supreme Court struck down **Section 66A of the Information Technology Act, 2000** as unconstitutional, holding it to be vague, overbroad, and having a **chilling effect** on the freedom of speech and expression guaranteed under Article 19(1)(a), without falling within the reasonable restrictions of Article 19(2).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00300', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 12, 'What was decided in Justice K.S. Puttaswamy v. Union of India (2017), the Right to Privacy case?', 'In ***Justice K.S. Puttaswamy v. Union of India* (2017)**, a nine-judge bench unanimously held that the **right to privacy** is a **fundamental right**, intrinsic to the right to life and personal liberty under **Article 21** and as part of the freedoms guaranteed by Part III, overruling the contrary observations in *M.P. Sharma* (1954) and *Kharak Singh* (1962) on this point.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00301', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 13, 'What was decided in Navtej Singh Johar v. Union of India (2018)?', 'In ***Navtej Singh Johar v. Union of India* (2018)**, a five-judge bench unanimously **decriminalised consensual same-sex relations** between adults by reading down **Section 377 of the IPC**, holding that it violated the rights to equality, privacy, dignity, and personal liberty under Articles 14, 15, 19, and 21.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00302', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 14, 'What was decided in Indian Young Lawyers Association v. State of Kerala (2018), the Sabarimala case?', 'In ***Indian Young Lawyers Association v. State of Kerala* (2018)**, the Supreme Court, by a 4-1 majority, held that the traditional exclusion of women of menstruating age (10-50 years) from the **Sabarimala temple** violated Articles 14, 15, 17, and 25, and that the practice did not constitute an ''essential religious practice'' warranting protection under Article 26. Subsequent review petitions led to the matter being referred to a larger bench.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00303', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 15, 'What was decided in Keshav Mills Co. Ltd. v. Commissioner of Income Tax, relevant to the doctrine of prospective overruling, or more notably in Golaknath regarding prospective overruling?', 'In ***I.C. Golaknath v. State of Punjab* (1967)**, the Supreme Court, for the first time in India, applied the American doctrine of **''prospective overruling''**, holding that its ruling (that Parliament could not amend Fundamental Rights) would operate only **prospectively**, leaving earlier constitutional amendments (such as the First, Fourth, and Seventeenth) undisturbed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00304', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 16, 'What was decided in Hussainara Khatoon v. State of Bihar (1979)?', 'In ***Hussainara Khatoon v. State of Bihar* (1979)**, the Supreme Court held that the **right to a speedy trial** is an essential and implicit part of the right to life and personal liberty guaranteed under **Article 21**, leading to the release of thousands of undertrial prisoners who had been incarcerated for periods exceeding the maximum sentence for their alleged offences.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00305', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 17, 'What was decided in Bandhua Mukti Morcha v. Union of India (1984)?', 'In ***Bandhua Mukti Morcha v. Union of India* (1984)**, the Supreme Court, acting on a letter treated as a writ petition (epistolary jurisdiction), held that the right to live with human dignity under **Article 21** includes protection against bonded labour and exploitation, and laid down guidelines for identification and rehabilitation of bonded labourers, significantly expanding the scope of **Public Interest Litigation (PIL)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00306', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 18, 'What was decided in Subhash Kumar v. State of Bihar (1991)?', 'In ***Subhash Kumar v. State of Bihar* (1991)**, the Supreme Court held that the **right to a clean and wholesome environment** is part of the right to life under **Article 21**, enabling citizens to approach the Court under Article 32 to prevent pollution of water and environment causing a hazard to health and life.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00307', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 19, 'What was decided in Unni Krishnan, J.P. v. State of Andhra Pradesh (1993)?', 'In ***Unni Krishnan, J.P. v. State of Andhra Pradesh* (1993)**, the Supreme Court held that the **right to education** up to the age of 14 is a Fundamental Right flowing from **Article 21**, read with the Directive Principle in Article 45 — a ruling that provided the foundation for the later insertion of **Article 21A** by the 86th Amendment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00308', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 20, 'What was decided in Nandini Satpathy v. P.L. Dani (1978)?', 'In ***Nandini Satpathy v. P.L. Dani* (1978)**, the Supreme Court held that the protection against self-incrimination under **Article 20(3)** extends to the **investigation stage**, not just trial, and that an accused cannot be forced to answer questions that may expose them to a criminal charge, reinforcing the right to silence during police interrogation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00309', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 21, 'What was decided in D.K. Basu v. State of West Bengal (1997)?', 'In ***D.K. Basu v. State of West Bengal* (1997)**, the Supreme Court laid down comprehensive **guidelines to prevent custodial violence and torture**, requiring police to prepare arrest memos, inform relatives of the arrest, conduct medical examinations, and maintain records — these guidelines were later substantially incorporated into the Code of Criminal Procedure through amendments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00310', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 22, 'What was decided in Shayara Bano v. Union of India (2017), the Triple Talaq case?', 'In ***Shayara Bano v. Union of India* (2017)**, a five-judge bench, by a 3-2 majority, held the practice of **''talaq-e-biddat'' (instant triple talaq)** among Muslims to be unconstitutional, being manifestly arbitrary and violative of Article 14, leading to the subsequent enactment of the Muslim Women (Protection of Rights on Marriage) Act, 2019 criminalising the practice.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00311', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 23, 'What was decided in Joseph Shine v. Union of India (2018)?', 'In ***Joseph Shine v. Union of India* (2018)**, the Supreme Court struck down **Section 497 of the IPC** (adultery), which criminalised a man having consensual sexual relations with a married woman without her husband''s consent, holding it violative of Articles 14, 15, and 21 for treating women as property of their husbands and being manifestly discriminatory.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00312', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 24, 'What was decided in Common Cause v. Union of India (2018) regarding passive euthanasia?', 'In ***Common Cause v. Union of India* (2018)**, the Supreme Court recognised the **right to die with dignity** as part of the right to life under Article 21, legally permitting **passive euthanasia** and recognising the validity of ''living wills''/advance medical directives, subject to detailed safeguards and procedural guidelines.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00313', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 25, 'What was decided in Lily Thomas v. Union of India (2013)?', 'In ***Lily Thomas v. Union of India* (2013)**, the Supreme Court struck down **Section 8(4) of the Representation of the People Act, 1951**, which had allowed convicted sitting MPs/MLAs a three-month window to appeal before disqualification, holding it unconstitutional and ruling that **disqualification takes immediate effect** upon conviction for specified offences.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00314', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 26, 'What was decided in Romesh Thappar v. State of Madras (1950)?', 'In ***Romesh Thappar v. State of Madras* (1950)**, one of the earliest free-speech rulings, the Supreme Court held that the freedom of speech and expression under **Article 19(1)(a)** includes the **freedom of the press**, and struck down a State order banning the entry of a journal as an unreasonable restriction not falling within the permissible grounds of Article 19(2) at the time.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00315', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 27, 'What was decided in Bennett Coleman & Co. v. Union of India (1973)?', 'In ***Bennett Coleman & Co. v. Union of India* (1973)**, the Supreme Court struck down the Newsprint Control Order restricting the number of pages newspapers could publish, holding that such restrictions on newsprint directly and adversely affected the **freedom of the press** under Article 19(1)(a), and could not be justified as a mere trade/business regulation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00316', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 28, 'What was decided in Kedar Nath Singh v. State of Bihar (1962)?', 'In ***Kedar Nath Singh v. State of Bihar* (1962)**, a Constitution Bench upheld the constitutional validity of **Section 124A IPC (sedition)** but significantly narrowed its scope, holding it applicable only to acts involving **incitement to violence or public disorder**, and not to mere criticism of the government, however strongly worded, in order to save the provision from being unconstitutional.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00317', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 29, 'What was decided in E.P. Royappa v. State of Tamil Nadu (1974)?', 'In ***E.P. Royappa v. State of Tamil Nadu* (1974)**, the Supreme Court propounded the **''new doctrine of equality''**, holding that equality under Article 14 is antithetic to **arbitrariness**, and that an arbitrary act necessarily involves negation of equality, thereby expanding Article 14 beyond the traditional ''reasonable classification'' test.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00318', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 30, 'What was decided in M. Nagaraj v. Union of India (2006)?', 'In ***M. Nagaraj v. Union of India* (2006)**, the Supreme Court upheld the validity of constitutional amendments permitting reservation in **promotions** for SC/ST employees, but held that the State must demonstrate **backwardness, inadequate representation, and overall administrative efficiency** before providing such reservation, subjecting it to these ''controlling conditions.''', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00319', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 31, 'What was decided in Kihoto Hollohan v. Zachillhu (1992)?', 'In ***Kihoto Hollohan v. Zachillhu* (1992)**, the Supreme Court upheld the constitutional validity of the **Tenth Schedule (anti-defection law)**, while holding that the Speaker/Chairman''s decision on disqualification acts as a tribunal and is subject to **limited judicial review** on grounds such as mala fides, perversity, or violation of constitutional mandates.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00320', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 32, 'What was decided in the Second Judges Case, Supreme Court Advocates-on-Record Association v. Union of India (1993)?', 'In the **Second Judges Case (1993)**, a nine-judge bench held that in the matter of appointment of judges, the **Chief Justice of India''s opinion, formed in consultation with a collegium of senior judges, would have primacy**, effectively originating the **collegium system** of judicial appointments and limiting executive discretion in the process.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00321', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 33, 'What was decided in Supreme Court Advocates-on-Record Association v. Union of India (2015), the NJAC case?', 'In the ***NJAC case* (2015)**, the Supreme Court struck down the **99th Constitutional Amendment Act** and the **National Judicial Appointments Commission (NJAC) Act, 2014**, holding that they violated the basic structure of the Constitution by compromising **judicial independence** and the primacy of the judiciary in appointments, thereby reviving the collegium system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00322', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 34, 'What was decided in Anuradha Bhasin v. Union of India (2020)?', 'In ***Anuradha Bhasin v. Union of India* (2020)**, concerning the internet shutdown in Jammu and Kashmir, the Supreme Court held that the **freedom of speech and expression and the freedom to carry on trade/business through the internet** are protected under Articles 19(1)(a) and 19(1)(g), and that any restriction (such as suspension of internet services) must satisfy the tests of **necessity and proportionality**, and orders imposing such restrictions must be published and reviewed periodically.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00323', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 35, 'What was decided in Keshavananda Bharati''s companion precedent, Indira Nehru Gandhi v. Raj Narain (1975)?', 'In ***Indira Nehru Gandhi v. Raj Narain* (1975)**, the Supreme Court struck down **Clause 4 of the 39th Constitutional Amendment**, which sought to place the Prime Minister''s election beyond judicial scrutiny, holding that it violated the basic structure principles of **free and fair elections** and the **rule of law**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00324', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 36, 'What was decided in Rustom Cavasjee Cooper v. Union of India (1970), the Bank Nationalisation case?', 'In ***Rustom Cavasjee Cooper v. Union of India* (1970)**, the Supreme Court struck down the Banking Companies (Acquisition and Transfer of Undertakings) Act, 1969 nationalising major banks, holding that the compensation provided was illusory, and significantly, that a law affecting a Fundamental Right must be tested against the **direct and inevitable effect** on the right, not merely the object of the legislation — overruling the narrow approach of *A.K. Gopalan* on this aspect.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00325', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 37, 'What was decided in Chief Settlement Commissioner v. Om Prakash, relevant to administrative law — or more notably in A.K. Kraipak v. Union of India (1969)?', 'In ***A.K. Kraipak v. Union of India* (1969)**, the Supreme Court held that the principles of **natural justice** apply not only to quasi-judicial functions but also to purely **administrative functions** that affect the rights of individuals, blurring the earlier rigid distinction between judicial, quasi-judicial, and administrative decision-making for the purposes of fair procedure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00326', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 38, 'What was decided in Maneka Gandhi''s companion case regarding passport impoundment and audi alteram partem?', '***Maneka Gandhi v. Union of India* (1978)** itself arose from the **impounding of the petitioner''s passport** without giving her a hearing; the Supreme Court held that even where a statute is silent, the principles of natural justice (audi alteram partem) must be read into the procedure, unless expressly excluded for compelling reasons, reinforcing fair administrative action.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00327', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 39, 'What was decided in Bachan Singh v. State of Punjab (1980)?', 'In ***Bachan Singh v. State of Punjab* (1980)**, a Constitution Bench upheld the validity of the **death penalty** under Section 302 IPC, holding it consistent with Articles 14, 19, and 21, but restricted its application to the **''rarest of rare'' cases**, requiring courts to record special reasons and weigh aggravating and mitigating circumstances.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00328', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 40, 'What was decided in Mithu v. State of Punjab (1983)?', 'In ***Mithu v. State of Punjab* (1983)**, the Supreme Court struck down **Section 303 IPC**, which provided for a **mandatory death sentence** for murder committed by a person already under a sentence of life imprisonment, holding that mandatory capital punishment, which denies judicial discretion to consider mitigating circumstances, violates Articles 14 and 21.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00329', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 41, 'What was decided in Sunil Batra v. Delhi Administration (1978)?', 'In ***Sunil Batra v. Delhi Administration* (1978)**, the Supreme Court held that **prisoners do not lose their Fundamental Rights**, including the right to live with human dignity under Article 21, merely by reason of incarceration, and condemned practices such as solitary confinement and the use of bar fetters without justification as violative of constitutional protections.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00330', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 42, 'What was decided in Gian Kaur v. State of Punjab (1996)?', 'In ***Gian Kaur v. State of Punjab* (1996)**, the Supreme Court upheld the constitutional validity of **Section 306 IPC (abetment of suicide)**, holding that the **''right to life'' under Article 21 does not include the right to die**, overruling the earlier contrary view on this point in *P. Rathinam v. Union of India* (1994), while clarifying that the question of euthanasia stood on a different footing (later addressed separately in *Common Cause*, 2018).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00331', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 43, 'What was decided in Francis Coralie Mullin v. Union Territory of Delhi (1981)?', 'In ***Francis Coralie Mullin v. Union Territory of Delhi* (1981)**, the Supreme Court gave an expansive meaning to **Article 21**, holding that the right to life includes the **right to live with human dignity**, encompassing the bare necessities of life such as adequate nutrition, clothing, shelter, and facilities for reading, writing, and expressing oneself.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00332', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 44, 'What was decided in Bodhisattwa Gautam v. Subhra Chakraborty (1996)?', 'In ***Bodhisattwa Gautam v. Subhra Chakraborty* (1996)**, the Supreme Court held that **rape is a crime against basic human rights** and a violation of the victim''s right to life under Article 21, and directed interim compensation to the victim under the Court''s power to do complete justice, reinforcing victim-centric criminal jurisprudence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00333', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 45, 'What was decided in P.N. Duda v. V.P. Shiv Shankar (1988) regarding contempt of court?', 'In ***P.N. Duda v. V.P. Shiv Shankar* (1988)**, the Supreme Court held that criticism of the judiciary, even if strongly worded, does not amount to contempt unless it crosses the limits and scandalises the court or obstructs the administration of justice, balancing the **freedom of speech** with the need to maintain the **dignity of courts**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00334', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 46, 'What was decided in Indira Jaising v. Supreme Court of India (2017), regarding the designation of Senior Advocates?', 'In ***Indira Jaising v. Supreme Court of India* (2017)**, the Supreme Court laid down comprehensive, objective **guidelines and a point-based system** for the designation of Senior Advocates by the Supreme Court and High Courts, aiming to bring transparency and remove arbitrariness from what had previously been a largely discretionary process.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00335', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 47, 'What was decided in Centre for Public Interest Litigation v. Union of India (2012), the 2G Spectrum case?', 'In ***Centre for Public Interest Litigation v. Union of India* (2012)**, the Supreme Court quashed 122 telecom licences granted through the **''first-come-first-served''** policy, holding that natural resources must generally be allocated through fair, transparent methods like **auction**, in furtherance of Article 14''s guarantee against arbitrariness in State action — though the Court later clarified in a Presidential Reference that auction is not the only constitutionally mandated method for all natural resources.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00336', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 48, 'What was decided in T.N. Godavarman Thirumulpad v. Union of India (ongoing from 1996)?', '***T.N. Godavarman Thirumulpad v. Union of India*, initiated in 1996**, is a landmark ''continuing mandamus'' case in which the Supreme Court has, over decades, issued a series of directions for **forest conservation**, broadening the definition of ''forest'' for regulatory purposes and establishing mechanisms like the Compensatory Afforestation Fund, becoming one of the most significant examples of judicial environmental governance in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00337', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 49, 'What was decided in Indian Council for Enviro-Legal Action v. Union of India (1996)?', 'In ***Indian Council for Enviro-Legal Action v. Union of India* (1996)**, the Supreme Court applied the **''polluter pays''** principle, holding industries responsible for environmental damage liable to compensate affected persons and remediate the damage caused, reinforcing that this principle, along with the precautionary principle, forms part of India''s environmental jurisprudence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00338', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 50, 'What was decided in Vellore Citizens Welfare Forum v. Union of India (1996)?', 'In ***Vellore Citizens Welfare Forum v. Union of India* (1996)**, the Supreme Court held that the **''precautionary principle''** and the **''polluter pays''** principle are essential features of **sustainable development** and part of the environmental law of India, binding on courts and authorities even without explicit statutory incorporation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00339', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 51, 'What was decided in Samatha v. State of Andhra Pradesh (1997)?', 'In ***Samatha v. State of Andhra Pradesh* (1997)**, the Supreme Court held that government land, including land belonging to tribals in Scheduled Areas, cannot be leased to private non-tribal entities for mining purposes, reinforcing the protective constitutional framework (under the Fifth Schedule) for the rights of **Scheduled Tribes** over their land and natural resources.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00340', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 52, 'What was decided in Aruna Ramchandra Shanbaug v. Union of India (2011)?', 'In ***Aruna Ramchandra Shanbaug v. Union of India* (2011)**, the Supreme Court first recognised the legality of **passive euthanasia** in India under strict conditions and judicial oversight (via High Court approval on a case-by-case basis), laying the groundwork that was later generalised and formalised with safeguards like living wills in *Common Cause v. Union of India* (2018).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00341', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 53, 'What was decided in Naz Foundation v. Government of NCT of Delhi (2009), prior to Navtej Singh Johar?', 'In ***Naz Foundation v. Government of NCT of Delhi* (2009)**, the Delhi High Court first read down **Section 377 IPC** to decriminalise consensual homosexual acts between adults, holding it violative of Articles 14, 15, and 21 — though this ruling was reversed by the Supreme Court in *Suresh Kumar Koushal v. Naz Foundation* (2013), before the Delhi High Court''s original reasoning was ultimately vindicated by the Constitution Bench in *Navtej Singh Johar* (2018).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00342', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 54, 'What was decided in People''s Union for Civil Liberties v. Union of India (1997), relating to telephone tapping?', 'In ***People''s Union for Civil Liberties v. Union of India* (1997)**, the Supreme Court held that **telephone tapping is a serious invasion of privacy**, and laid down procedural safeguards (later incorporated into Rule 419A of the Telegraph Rules) requiring authorisation from the Home Secretary and periodic review before any interception order could be validly issued, under the then-applicable Indian Telegraph Act, 1885.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00343', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 55, 'What was decided in S.P. Gupta v. Union of India (1981), the First Judges Case?', 'In ***S.P. Gupta v. Union of India* (1981)**, the First Judges Case, the Supreme Court held that the term **''consultation''** with the Chief Justice of India in judicial appointments under Articles 124 and 217 did **not** mean ''concurrence,'' giving **primacy to the executive** in appointment and transfer of judges — a position later reversed in favour of judicial primacy by the Second Judges Case (1993).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00344', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 56, 'What was decided in Nilabati Behera v. State of Orissa (1993)?', 'In ***Nilabati Behera v. State of Orissa* (1993)**, the Supreme Court held that the State is liable to pay **monetary compensation** for custodial death as a remedy under public law (based on the constitutional tort doctrine), distinct from and in addition to any remedy available under private law (tort) or criminal law, where there is established violation of Fundamental Rights by State agents.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00345', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 57, 'What was decided in Rudul Sah v. State of Bihar (1983)?', 'In ***Rudul Sah v. State of Bihar* (1983)**, the Supreme Court, for the first time, awarded **monetary compensation** under Article 32 to a person who had been illegally detained in prison for over 14 years after his acquittal, establishing that compensation can be a valid remedy for violation of Fundamental Rights under the Court''s writ jurisdiction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00346', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 58, 'What was decided in M. Siddiq v. Mahant Suresh Das (2019), the Ayodhya title suit?', 'In ***M. Siddiq v. Mahant Suresh Das* (2019)**, a five-judge bench of the Supreme Court unanimously decided the **Ayodhya land title dispute**, awarding the disputed site to a trust for the construction of a temple, while directing the allotment of alternative land for a mosque, resolving one of India''s longest-running civil litigations on grounds of evidentiary findings rather than questions of religious faith.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00347', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 59, 'What was decided in the Coelho case, I.R. Coelho v. State of Tamil Nadu (2007)?', 'In ***I.R. Coelho v. State of Tamil Nadu* (2007)**, a nine-judge bench held that laws placed in the **Ninth Schedule after 24 April 1973** (the date of the Kesavananda Bharati judgment) are **not automatically immune** from judicial review, and can be tested against the basic structure doctrine if they violate Fundamental Rights in Articles 14, 19, or 21.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00348', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 60, 'What was decided in Maneka Gandhi regarding the right to travel abroad?', '***Maneka Gandhi v. Union of India* (1978)** specifically held that the **right to travel abroad** is part of the ''personal liberty'' guaranteed under **Article 21**, and that its restriction (through impounding of a passport) must follow a fair, just, and reasonable procedure, not merely any procedure enacted by a competent legislature.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00349', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 61, 'What was decided in Pathumma v. State of Kerala (1978)?', 'In ***Pathumma v. State of Kerala* (1978)**, the Supreme Court upheld the Kerala Agriculturists'' Debt Relief Act and elaborated the test for **reasonable restrictions** on the freedom to carry on business/trade under Article 19(1)(g), holding that restrictions must have a rational relation to the object sought to be achieved and must not be arbitrary or excessive.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00350', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 62, 'What was decided in R. Rajagopal v. State of Tamil Nadu (1994), the ''Auto Shankar'' case?', 'In ***R. Rajagopal v. State of Tamil Nadu* (1994)**, the Supreme Court recognised the **right to privacy** as implicit in Article 21, while balancing it against the freedom of the press, holding that public officials cannot generally claim privacy in relation to their **public duties**, barring certain exceptions like matters concerning privacy of women relating to sexual assault, kidnapping, etc.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00351', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 63, 'What was decided in Sahara India Real Estate Corp. v. SEBI (2012), on the postponement of publication?', 'In ***Sahara India Real Estate Corp. v. SEBI* (2012)**, the Supreme Court recognised the doctrine of **''postponement orders''** to balance the freedom of the press under Article 19(1)(a) with the right to a fair trial under Article 21, permitting courts, in exceptional cases, to temporarily restrain the publication of prejudicial material during the pendency of proceedings.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00352', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 64, 'What was decided in Champakam Dorairajan v. State of Madras (1951)?', 'In ***State of Madras v. Champakam Dorairajan* (1951)**, the Supreme Court struck down a communal reservation order for college admissions as violative of **Article 29(2)**, holding that Directive Principles cannot override Fundamental Rights — a ruling that directly led to the **First Constitutional Amendment, 1951**, which inserted Article 15(4) to permit special provisions for backward classes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00353', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 65, 'What was decided in Sajjan Singh v. State of Rajasthan (1965)?', 'In ***Sajjan Singh v. State of Rajasthan* (1965)**, the Supreme Court held, by majority, that Parliament''s power to amend the Constitution under **Article 368** extends to **Fundamental Rights** as well, since a constitutional amendment is not ''law'' within the meaning of Article 13(2) — a position later reversed in *Golaknath* (1967) and subsequently qualified by the basic structure doctrine in *Kesavananda Bharati* (1973).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00354', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 66, 'What was decided in Shankari Prasad v. Union of India (1951)?', 'In ***Shankari Prasad v. Union of India* (1951)**, the first case challenging a constitutional amendment, the Supreme Court held that the power to amend the Constitution, including Part III (Fundamental Rights), under **Article 368** is **not ''law''** within the meaning of Article 13(2), and is therefore not subject to the bar against abridging Fundamental Rights — a view affirmed in *Sajjan Singh* (1965) but overruled in *Golaknath* (1967).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00355', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 67, 'What was decided in Bijoe Emmanuel v. State of Kerala (1986), the ''National Anthem'' case?', 'In ***Bijoe Emmanuel v. State of Kerala* (1986)**, the Supreme Court held that expelling Jehovah''s Witness schoolchildren for not singing the national anthem (while standing respectfully) violated their **freedom of religion under Article 25**, since there is no legal provision compelling anyone to sing the anthem, and respectful silence did not show disrespect under the Prevention of Insults to National Honour Act, 1971.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00356', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 68, 'What was decided in S.P. Mittal v. Union of India (1983) and other cases on what constitutes ''religion''?', 'Indian courts, including in ***S.P. Mittal v. Union of India* (1983)**, have held that ''religion'' under Articles 25-26 is a matter of **belief and doctrine** concerning the conscience and spiritual well-being of a person, and that courts apply the **''essential religious practices'' test** to determine which specific practices of a faith or denomination are constitutionally protected as integral to that religion, as opposed to secular or superstitious accretions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00357', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 69, 'What was decided in In Re: Article 370 of the Constitution (2023)?', 'In ***In Re: Article 370 of the Constitution* (2023)**, a five-judge bench of the Supreme Court upheld the constitutional validity of the **2019 Presidential Order abrogating the special status of Jammu and Kashmir** under Article 370, holding that the provision was always a **temporary provision** intended to facilitate the gradual integration of the State, and that the President''s power to declare it inoperative was validly exercised.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00358', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 70, 'What procedural safeguard did the Supreme Court read into eviction of unauthorised occupants in Olga Tellis v. Bombay Municipal Corporation (1985)?', 'In ***Olga Tellis v. Bombay Municipal Corporation* (1985)**, beyond recognising livelihood as part of Article 21, the Court held that even where eviction of pavement dwellers is otherwise permissible, the procedure adopted must still comply with principles of **fairness and reasonableness** (including prior notice and an opportunity to be heard), reflecting the broader due-process reading of Article 21 established in *Maneka Gandhi*.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00359', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 71, 'What was decided in Sheela Barse v. Union of India (1986), regarding women prisoners and children?', 'In ***Sheela Barse v. Union of India* (1986)**, the Supreme Court issued directions for the protection of **women prisoners in police custody**, including separate lock-ups, presence of female constables, and prompt medical examination, reinforcing the principle that fundamental rights, including protection from custodial abuse, survive incarceration.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00360', 'judiciary-law-bank', 'Legal GK & Landmark Judgments', 4, 72, 'What was decided in Chintaman Rao v. State of Madhya Pradesh (1950)?', 'In ***Chintaman Rao v. State of Madhya Pradesh* (1950)**, the Supreme Court held that the phrase **''reasonable restriction''** connotes that the limitation imposed on a Fundamental Right must not be arbitrary or excessive in nature, and must strike a proper balance between the freedom guaranteed and the social control permitted under Article 19 — a foundational early articulation of the reasonableness standard.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00361', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 0, 'What is the ''Natural Law'' school of jurisprudence?', 'The **Natural Law** school holds that law derives its validity and authority from **universal moral principles** inherent in nature, reason, or divine order, which exist independently of human enactment. Proponents range from ancient thinkers like **Aristotle** and **Cicero** to medieval theorists like **St. Thomas Aquinas**, who held that human (positive) law must conform to natural/moral law to be truly valid.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00362', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 1, 'What is ''Legal Positivism'' as a school of jurisprudence?', '**Legal Positivism** holds that law is a body of rules **validly made by a sovereign or competent authority**, separate from morality — ''is'' and ''ought'' are distinct. Its key proponents include **John Austin** (command theory of law) and **H.L.A. Hart** (rule-based theory distinguishing primary and secondary rules), who rejected the necessity of a moral foundation for a rule''s legal validity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00363', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 2, 'What is John Austin''s ''command theory'' of law?', '**John Austin''s command theory**, propounded in *The Province of Jurisprudence Determined* (1832), defines law as a **command of the sovereign**, backed by a **sanction**, and habitually obeyed by the bulk of the population. Austin distinguished ''positive law'' (properly so-called) from morality, religion, and other normative systems that lack an identifiable political sovereign and sanction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00364', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 3, 'What is H.L.A. Hart''s theory of ''primary and secondary rules''?', '**H.L.A. Hart**, in *The Concept of Law* (1961), critiqued Austin''s command theory and proposed that a legal system consists of **primary rules** (imposing duties/obligations on citizens) and **secondary rules** — the **rule of recognition** (identifying valid primary rules), **rule of change** (for altering rules), and **rule of adjudication** (for resolving disputes) — together forming the ''union'' that constitutes a mature legal system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00365', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 4, 'What is Hans Kelsen''s ''Pure Theory of Law'' and the concept of ''Grundnorm''?', '**Hans Kelsen''s Pure Theory of Law** seeks to study law as a **''normative science''**, free from moral, political, or sociological considerations. He proposed a hierarchical structure of norms deriving validity from a basic, hypothetical norm called the **''Grundnorm''** (basic norm), which is presupposed and itself not derived from any other norm, and from which the entire legal system''s validity ultimately flows.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00366', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 5, 'What is the ''Historical School'' of jurisprudence, as propounded by Friedrich Carl von Savigny?', 'The **Historical School**, led by **Friedrich Carl von Savigny**, holds that law is not consciously created by legislators but develops **organically**, like language or custom, from the **''Volksgeist''** (spirit of the people) — reflecting the history, traditions, and consciousness of a community, and growing gradually with the development of society rather than being imposed from above.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00367', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 6, 'What is the ''Sociological School'' of jurisprudence associated with Roscoe Pound?', 'The **Sociological School**, associated with **Roscoe Pound**, views law as a tool of **''social engineering''**, balancing competing individual, public, and social interests to achieve maximum social welfare with minimum friction. Pound emphasised studying the actual social effects and functioning of law (''law in action'') rather than merely its abstract rules (''law in books'').', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00368', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 7, 'What is the ''Analytical School'' of jurisprudence?', 'The **Analytical School** (closely related to legal positivism) focuses on analysing the **structure, concepts, and logical relationships** of an existing legal system as it actually is, without concern for its moral merit or historical origin. Key figures include **Jeremy Bentham**, **John Austin**, and later **H.L.A. Hart**, who sought precise, systematic definitions of legal concepts like rights, duties, and sovereignty.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00369', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 8, 'What is ''Legal Realism'' as a jurisprudential school?', '**Legal Realism**, associated with American scholars like **Oliver Wendell Holmes Jr.** and **Karl Llewellyn**, emphasises studying what courts **actually do** in practice rather than abstract legal rules, famously described by Holmes as **''the prophecies of what the courts will do in fact''** — stressing that judicial decisions are influenced by social, economic, and psychological factors beyond pure legal logic.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00370', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 9, 'What is the distinction between ''substantive law'' and ''procedural law''?', '**Substantive law** defines, creates, and regulates **rights, duties, and liabilities** (e.g., the Indian Penal Code, Contract Act), determining what conduct is permitted or prohibited.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00371', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 10, 'What is the distinction between ''public law'' and ''private law''?', '**Public law** governs the relationship between the **State and individuals**, or between different organs of the State, and includes constitutional law, administrative law, and criminal law.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00372', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 11, 'What are the ''sources of law'' recognised in jurisprudence?', 'Jurisprudence generally recognises several sources of law, including **legislation** (enacted by a competent legislature), **precedent/case law** (judicial decisions), **custom** (long-established practices recognised as binding), and **juristic/personal opinion or doctrine** (treatises of legal scholars), each contributing differently depending on the legal system (common law vs civil law traditions).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00373', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 12, 'What is the doctrine of ''separation of powers'' as propounded by Montesquieu?', '**Montesquieu**, in *The Spirit of the Laws* (1748), propounded the **doctrine of separation of powers**, advocating that the **legislative, executive, and judicial** functions of government should be vested in separate, independent organs to prevent concentration of power and safeguard liberty. India follows a **functional separation with checks and balances** rather than a rigid, watertight separation as in the United States.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00374', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 13, 'What is the ''rule of law'' as propounded by A.V. Dicey?', '**A.V. Dicey** formulated the **rule of law** doctrine with three core elements: (i) **supremacy of law** over arbitrary power, (ii) **equality before law**, with no person above the law, and (iii) that constitutional rights flow from **ordinary law of the land** as determined by courts, rather than from a written constitution alone. The Indian Supreme Court has recognised the rule of law as part of the Constitution''s basic structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00375', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 14, 'What is ''John Rawls''s theory of justice'' and the ''veil of ignorance''?', '**John Rawls**, in *A Theory of Justice* (1971), proposed that principles of justice should be chosen from behind a hypothetical **''veil of ignorance''** — where individuals do not know their own social position, talents, or circumstances — ensuring impartial principles, including the **''difference principle''**, which permits social/economic inequalities only if they benefit the least advantaged members of society.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00376', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 15, 'What is Jeremy Bentham''s theory of ''Utilitarianism''?', '**Jeremy Bentham''s Utilitarianism** holds that the rightness of laws and actions should be judged by their tendency to promote the **''greatest happiness of the greatest number''**, measuring pleasure and pain through a ''felicific calculus.'' Bentham was also a strong critic of natural law and judge-made law, advocating codification of laws.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00377', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 16, 'What is the concept of ''legal rights'' and their essential elements?', 'A **legal right** is an interest recognised and protected by law, the violation of which would be a legal wrong. Jurists like **Salmond** identify essential elements of a legal right: a **person** entitled to the right (subject), a **person** bound by a corresponding duty, the **content/subject-matter** of the right, and the **title** by which the right vests in its holder.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00378', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 17, 'What is the Hohfeldian analysis of jural relations?', '**Wesley Newcomb Hohfeld** analysed legal rights into four pairs of **jural correlatives and opposites**: **right-duty**, **privilege (liberty)-no-right**, **power-liability**, and **immunity-disability** — providing a precise analytical framework to clarify the often loosely used term ''right'' in legal discourse.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00379', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 18, 'What is the distinction between ''right in rem'' and ''right in personam''?', 'A **right in rem** is available against the **world at large** (e.g., ownership of property), binding all persons generally.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00380', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 19, 'What is the concept of ''legal personality'' and who/what can be a ''legal person''?', '**Legal personality** refers to the capacity to hold rights and duties recognised by law. Besides natural persons (human beings), the law recognises **juristic/artificial persons**, such as **companies** (as held in *Salomon v. Salomon & Co.* (1897), establishing the doctrine of separate corporate personality), **statutory corporations**, and even certain entities like idols or, as per some Indian court rulings, rivers, for limited purposes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00381', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 20, 'What is the doctrine of ''lifting the corporate veil''?', 'The **doctrine of lifting (or piercing) the corporate veil** allows courts, in certain exceptional circumstances (such as fraud, evasion of legal obligations, or where the company is a mere sham/façade), to disregard the separate legal personality of a company and look at the **real persons behind it** (shareholders/directors), holding them personally liable, departing from the general rule established in *Salomon v. Salomon & Co.* (1897).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00382', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 21, 'What is the concept of ''possession'' in jurisprudence, as distinguished from ''ownership''?', '**Possession** refers to **physical/factual control** over a thing, coupled with the intention to hold it as one''s own (corpus and animus possidendi), and is protected by law even against persons other than the true owner.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00383', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 22, 'What is the distinction between ''civil wrong'' and ''criminal wrong''?', 'A **civil wrong** is a private wrong against an individual, remedied through **compensation/damages** sought by the aggrieved party in a civil suit (e.g., breach of contract, tort).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00384', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 23, 'What are the theories/purposes of punishment recognised in jurisprudence?', 'Jurisprudence recognises several theories of punishment: the **deterrent theory** (discouraging future crime through fear of punishment), the **retributive theory** (punishment as just desert for the wrong done), the **preventive/incapacitative theory** (disabling the offender from repeating the crime), the **reformative/rehabilitative theory** (reforming the offender''s character), and the **compensatory theory** (compensating the victim for loss suffered).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00385', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 24, 'What is ''custom'' as a source of law, and what are the essential tests for a valid legal custom?', '**Custom** is a long-established practice that has acquired the force of law through consistent and uniform observance. For a custom to be legally valid, jurists require it to be: **ancient/immemorial**, **continuous**, **reasonable**, **certain**, and **not opposed to public policy or morality**, and it must have been observed as of right, not merely by way of courtesy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00386', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 25, 'What is the concept of ''stare decisis'' and its rationale in common law systems?', '**Stare decisis** (''to stand by things decided'') is the doctrine of **binding judicial precedent**, requiring courts to follow the ratio decidendi of earlier decisions of superior or coordinate courts in similar matters. It promotes **certainty, predictability, consistency, and equality** before the law, though courts may distinguish, overrule, or depart from precedent under specific circumstances.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00387', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 26, 'What is the distinction between ''declaratory'' and ''original'' precedent?', 'A **declaratory precedent** merely applies and declares an already existing rule of law to the facts of a new case.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00388', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 27, 'What is the concept of ''equity'' in jurisprudence, and how does it relate to common law?', '**Equity** developed in English legal history as a body of principles administered by the Court of Chancery to **supplement and correct the rigidity** of the common law, based on notions of fairness, conscience, and justice (e.g., remedies like injunctions, specific performance, and trusts). Though the two systems were historically separate (administered by different courts), they have since been **fused procedurally** in most common law jurisdictions, including India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00389', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 28, 'What is the concept of ''legal fiction''?', 'A **legal fiction** is an assumption made by law that something is true, even though it may not be factually so, in order to achieve a particular legal consequence or do justice — for example, treating a company as a ''legal person'' distinct from its shareholders, or deeming the date of a decree to relate back to an earlier event for limited purposes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00390', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 29, 'What is the concept of ''delegated legislation'' and why does it arise?', '**Delegated legislation** (also called subordinate or secondary legislation) refers to rules, regulations, by-laws, or notifications made by the **executive or an administrative authority** under powers conferred by a parent statute enacted by the legislature. It arises due to the legislature''s limited time and expertise to deal with technical or evolving matters, allowing flexibility, while remaining subject to the limits of the enabling statute and the principle against **''excessive delegation''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00391', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 30, 'What is the ''doctrine of excessive delegation''?', 'The **doctrine against excessive delegation** holds that while a legislature may delegate ancillary or subordinate legislative functions (such as filling in details) to the executive, it **cannot delegate its essential legislative function** — namely, determining fundamental legislative policy — to any other body, and any such delegation that abdicates this core function is unconstitutional.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00392', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 31, 'What is ''Dworkin''s theory of law as integrity'' and the concept of legal ''principles'' versus ''rules''?', '**Ronald Dworkin**, a critic of Hart''s positivism, argued that law consists not merely of **''rules''** but also **''principles''** (broader standards of justice and fairness) which judges must apply, particularly in hard cases. His theory of **''law as integrity''** envisions judges as seeking the interpretation that best fits and justifies the legal community''s practices as a coherent, principled whole.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00393', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 32, 'What is the concept of ''Marxist jurisprudence'' or the Marxist theory of law?', '**Marxist jurisprudence**, rooted in the writings of **Karl Marx and Friedrich Engels**, views law primarily as an instrument of the **ruling (economically dominant) class** to maintain and legitimise existing social and economic structures, and predicts that law and the State will eventually **''wither away''** with the emergence of a classless, communist society.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00394', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 33, 'What is ''feminist jurisprudence''?', '**Feminist jurisprudence** critically examines how law has historically been shaped by and perpetuates **patriarchal structures and gender bias**, seeking to expose and remedy legal doctrines, institutions, and practices that disadvantage women, while advocating for substantive (rather than merely formal) equality in legal rules and their application.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00395', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 34, 'What is the ''Command Theory'' critique offered by H.L.A. Hart against Austin?', '**H.L.A. Hart** critiqued Austin''s command theory on several grounds: it cannot adequately explain power-conferring rules (e.g., rules enabling people to make wills or contracts), it fails to account for the **continuity** of law-making authority across successive sovereigns, and it cannot explain why laws continue to bind even the sovereign who made them, or why customary rules are treated as law despite lacking an explicit command.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00396', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 35, 'What is the ''basic norm'' or Grundnorm''s relationship to the Indian Constitution, per jurists?', 'Many Indian legal theorists treat the **Constitution of India itself as the ''Grundnorm''** (basic norm) in the Kelsenian sense, since it is the ultimate source from which the validity of all other laws in India is derived, and all ordinary legislation must conform to it to be considered legally valid.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00397', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 36, 'What is the distinction between ''codified law'' and ''uncodified (common) law''?', '**Codified law** refers to law that has been systematically collected, organised, and enacted in the form of a comprehensive statute/code (e.g., the Indian Penal Code, the Indian Contract Act).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00398', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 37, 'What is the concept of ''natural justice'' as a set of procedural principles?', '**Natural justice** comprises minimum procedural safeguards that must be observed in administrative, quasi-judicial, and (increasingly) even purely administrative decisions affecting a person''s rights, chiefly: **audi alteram partem** (right to a fair hearing) and **nemo judex in causa sua** (rule against bias), both aimed at ensuring fairness and preventing arbitrary exercise of power.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00399', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 38, 'What is the distinction between ''mandatory'' and ''directory'' provisions in statutory interpretation?', 'A **mandatory provision** must be strictly complied with, and non-compliance renders the resulting action **invalid/void**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00400', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 39, 'What is the concept of ''sovereignty'' in jurisprudence?', '**Sovereignty** refers to the **supreme, final, and absolute authority** within a political society, recognised as the source of all legal power and not itself subject to any other authority. Jurists distinguish between **de jure sovereignty** (legal/rightful authority) and **de facto sovereignty** (actual, effective control), and between **internal sovereignty** (supreme authority within the State) and **external sovereignty** (independence from other States).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00401', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 40, 'What is the concept of ''law and morality'' debate (the Hart-Fuller/Hart-Devlin debates)?', 'The classic jurisprudential debates on **law and morality** include the **Hart-Fuller debate** (on whether grossly immoral enactments, such as Nazi laws, should be regarded as ''law'' at all) and the **Hart-Devlin debate** (on whether the law should enforce a society''s shared morality, e.g., regarding private consensual conduct). Hart generally argued for separating law from morality for analytical clarity, while Fuller and Devlin emphasised law''s inherent connection to a moral order or shared social morality respectively.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00402', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 41, 'What is Lon Fuller''s concept of the ''inner morality of law''?', '**Lon Fuller**, in *The Morality of Law* (1964), argued that law has an **''inner morality''** comprising eight procedural principles necessary for a system of rules to function as law at all — including generality, publicity, prospectivity (non-retroactivity), clarity, non-contradiction, possibility of compliance, constancy, and congruence between rules and their actual administration — arguing that gross departures from these principles mean a system fails to qualify as ''law'' in the fullest sense.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00403', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 42, 'What is the concept of ''res nullius'' and ''res communis'' in property jurisprudence?', '**Res nullius** refers to property that belongs to **no one** and is capable of being acquired by the first person to take possession of it (e.g., wild animals in their natural state).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00404', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 43, 'What is the ''command and sanction'' critique of international law''s status as ''law''?', 'Under **Austin''s command theory**, international law was often doubted as ''true law'' because it lacks a single identifiable sovereign and a centralised, coercive sanction enforceable against States. Modern jurisprudence (e.g., Hart''s rule of recognition approach) instead views international law as a **distinct, evolving normative system**, binding through State consent, custom, and institutional enforcement mechanisms, even without a world sovereign.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00405', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 44, 'What is meant by ''judicial activism'' as opposed to ''judicial restraint''?', '**Judicial activism** refers to courts taking a proactive role in interpreting the Constitution/law expansively, sometimes creatively filling legislative or executive gaps to protect rights or advance social justice (e.g., through PIL and guidelines like Vishaka).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00406', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 45, 'What is the concept of ''Public Interest Litigation (PIL)'' in Indian jurisprudence?', '**Public Interest Litigation (PIL)** is a judicially evolved mechanism allowing any public-spirited person (not necessarily the aggrieved party) to approach the **Supreme Court (Article 32)** or **High Courts (Article 226)** on behalf of persons unable to approach the court themselves due to poverty, disability, or social/economic disadvantage, substantially relaxing the traditional requirement of **locus standi** to widen access to justice.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00407', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 46, 'What is ''epistolary jurisdiction'' as a facet of Indian judicial innovation?', '**Epistolary jurisdiction** refers to the practice, pioneered by the Indian Supreme Court, of treating **letters or postcards** addressed to the Court by or on behalf of aggrieved persons (especially the poor and marginalised) as writ petitions, dispensing with formal procedural requirements to facilitate access to justice in cases of gross violation of rights.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00408', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 47, 'What is the concept of ''continuing mandamus'' used by Indian courts?', 'A **''continuing mandamus''** is a judicial technique where a court, instead of issuing a single final order, retains seisin (control) over a matter and issues a **series of successive directions over time**, monitoring compliance by the executive/authorities — used extensively in cases involving environmental protection, prison reform, and other systemic governance failures.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00409', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 48, 'What is the distinction between ''jus cogens'' and ordinary rules of international law?', '**Jus cogens** (''compelling law'') refers to **peremptory norms of international law** that are accepted by the international community as a whole as norms from which **no derogation is permitted** (e.g., prohibitions on genocide, slavery, torture) — any treaty conflicting with a jus cogens norm is void, unlike ordinary customary or treaty-based rules, which States may generally modify by mutual agreement.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00410', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 49, 'What is the concept of ''social contract theory'' and its key proponents?', '**Social contract theory** posits that political authority and legal obligation arise from an implicit or hypothetical **agreement among individuals** to form a society and government, surrendering certain natural freedoms in exchange for order and protection. Key proponents include **Thomas Hobbes** (justifying absolute sovereignty to escape a brutal ''state of nature''), **John Locke** (limited government protecting natural rights to life, liberty, and property), and **Jean-Jacques Rousseau** (sovereignty resting in the ''general will'' of the people).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00411', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 50, 'What is Thomas Hobbes''s view of the ''state of nature'' and the social contract?', '**Thomas Hobbes**, in *Leviathan* (1651), described the state of nature as a condition of **''war of all against all''**, where life is ''solitary, poor, nasty, brutish, and short.'' To escape this, individuals surrender their natural rights to an **absolute sovereign (Leviathan)** through a social contract, who alone can guarantee peace and security, justifying strong, centralised political authority.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00412', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 51, 'What is John Locke''s theory of natural rights and limited government?', '**John Locke**, in *Two Treatises of Government* (1689), argued that individuals possess **natural/inalienable rights** to life, liberty, and property even in the state of nature, and form governments through a social contract **solely to better protect these rights**. Crucially, Locke held that if a government fails this trust or becomes tyrannical, the people retain the **right to resist and replace it** — a theory that influenced modern constitutionalism and limited government.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00413', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 52, 'What is Jean-Jacques Rousseau''s concept of the ''general will''?', '**Jean-Jacques Rousseau**, in *The Social Contract* (1762), argued that true sovereignty rests with the people collectively, expressed through the **''general will''** — the common interest of the community as a whole, which may differ from the mere sum of individual private interests (''will of all'') — and that legitimate laws must conform to this general will to command genuine political obligation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00414', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 53, 'What is the distinction between ''command'' theories and ''consent'' theories of political/legal obligation?', '**Command theories** (e.g., Austin, Hobbes) ground legal/political obligation in the authority and coercive power of the sovereign, requiring obedience regardless of individual agreement.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00415', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 54, 'What is the concept of ''living law'' as propounded by Eugen Ehrlich?', '**Eugen Ehrlich**, a founder of the sociology of law, propounded the concept of **''living law''** — the body of rules that actually govern social life and are observed by people in practice, which may differ substantially from the formal **''law in the books''** enacted by the State, emphasising that the true source of legal norms often lies in social facts and associations rather than state command.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00416', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 55, 'What is the concept of ''legal certainty'' and why is it considered a core value of law?', '**Legal certainty** refers to the predictability and clarity of legal rules, enabling individuals to know in advance the legal consequences of their actions and to plan their affairs accordingly. It underlies doctrines such as **stare decisis**, the rule against retrospective (ex post facto) criminal laws, and the principle of legality (nulla poena sine lege), and is considered essential to the **rule of law**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00417', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 56, 'What is the concept of ''distributive'' and ''corrective'' justice as per Aristotle?', '**Aristotle** distinguished **distributive justice** — concerned with the fair allocation of benefits/burdens (such as wealth, honours) among members of a community in proportion to merit — from **corrective (rectificatory) justice** — concerned with restoring an equal balance between parties disturbed by a wrongful act (e.g., through compensation), irrespective of the parties'' relative social merit.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00418', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 57, 'What is the ''purposive approach'' to statutory interpretation?', 'The **purposive approach** to interpretation requires courts to construe a statute in light of its **underlying purpose or object**, rather than confining themselves strictly to the literal wording, particularly where literal interpretation would frustrate the legislative intent — it is closely linked to the mischief rule but is applied more broadly to modern welfare and regulatory legislation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00419', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 58, 'What is the concept of ''legal pluralism''?', '**Legal pluralism** refers to the coexistence of **multiple legal systems or sources of normative authority** within a single social or geographic space — for instance, in India, the coexistence of statutory law, personal laws of different religious communities, customary tribal laws, and constitutional law, each operating in overlapping or distinct spheres.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00420', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 59, 'What is the distinction between ''retributive justice'' and ''restorative justice''?', '**Retributive justice** focuses on **punishing** the offender proportionately to the wrong committed, viewing punishment as a deserved consequence of the crime.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00421', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 60, 'What is Salmond''s definition of law, and how does it differ from Austin''s?', '**Sir John Salmond** defined law as **''the body of principles recognised and applied by the State in the administration of justice''**, focusing on the courts as the primary institution through which law operates, rather than on the sovereign''s command as emphasised by **Austin**. Salmond''s approach ties the concept of law closely to its enforcement and recognition in actual judicial proceedings.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00422', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 61, 'What is the concept of ''ownership'' as analysed by Austin and Salmond?', '**Austin** described **ownership** as a right indefinite in point of user, unrestricted in point of disposition, and unlimited in point of duration over a determinate thing.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00423', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 62, 'What is the ''imperative theory'' of law, and who are its main proponents?', 'The **imperative theory** of law views law essentially as a **command or order** issued by a political superior (sovereign) to a political inferior, backed by the threat of sanction for disobedience. Its chief proponents are **Jeremy Bentham** and **John Austin**, who treated law as fundamentally distinct from morality or custom, deriving its binding force purely from the sovereign''s authority.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00424', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 63, 'What is the concept of ''duty'' in jurisprudence, and what is its relation to a ''right''?', 'A **duty** is an obligation imposed by law on a person to do or abstain from doing a particular act, and it is generally the **correlative** of a right — i.e., for every legal right held by one person, there exists a corresponding duty on another (or on persons generally) not to interfere with that right, as formalised in the Hohfeldian analysis of jural relations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00425', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 64, 'What is the ''command theory'' distinction between ''law properly so called'' and ''law improperly so called'' under Austin?', '**Austin** distinguished **''law properly so-called''** — commands issued by a political sovereign, backed by sanctions, to persons in a state of subjection — from **''law improperly so-called''**, which includes rules lacking a political superior''s command, such as rules of international law, constitutional conventions, and rules of clubs or associations, which Austin treated as mere **''positive morality''** rather than true law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00426', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 65, 'What is the significance of the ''grundnorm'' being ''presupposed'' rather than enacted, per Kelsen?', 'According to **Hans Kelsen**, the **Grundnorm (basic norm)** is not itself created or enacted by any higher authority but is **logically presupposed** as the ultimate source of validity for an entire legal order — it cannot be tested for its own validity, since doing so would require an infinite regress; its acceptance is a precondition for treating any norm within the system as legally binding.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00427', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 66, 'What is the concept of ''analogy'' as a method of filling gaps in law?', '**Analogy** is a method by which courts resolve a case not explicitly covered by existing statutory or precedential rules, by applying the **principle underlying a similar, already-decided rule or provision** to the new, comparable situation, thereby extending the law''s reach without requiring fresh legislation, though it is applied cautiously, especially in criminal law where strict construction is preferred.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00428', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 67, 'What is the concept of ''strict construction'' in the interpretation of penal statutes?', 'The principle of **strict construction** requires that penal (criminal) statutes be interpreted narrowly and in favour of the accused where genuine ambiguity exists, since such statutes impose liability and restrict individual liberty — courts will not extend criminal liability by implication or analogy beyond what the plain words of the statute clearly cover.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00429', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 68, 'What is Roscoe Pound''s classification of ''interests'' protected by law?', '**Roscoe Pound** classified the interests law must balance into three categories: **individual interests** (personality, domestic relations, property), **public interests** (interests of the State as a juristic/political entity), and **social interests** (general security, conservation of social resources, general morals, and individual life), with law functioning as a mechanism of ''social engineering'' to reconcile these competing claims.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00430', 'judiciary-law-bank', 'Jurisprudence & Legal Theory', 5, 69, 'What is the concept of ''customary international law'' and ''opinio juris''?', '**Customary international law** arises from a general and consistent **practice of States**, followed out of a sense of legal obligation known as **''opinio juris''** (as opposed to mere habit or courtesy), and it binds States even without a written treaty, forming one of the principal sources of international law recognised under Article 38 of the Statute of the International Court of Justice.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00431', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 0, 'What did the First Amendment Act, 1951 introduce?', 'The **First Amendment Act, 1951** inserted **Articles 31A and 31B** along with the **Ninth Schedule** (to protect land reform laws from judicial review), added reasonable restriction grounds (public order, friendly relations with foreign states, incitement to an offence) to Article 19(2), and inserted **Article 15(4)** enabling special provisions for socially and educationally backward classes, in response to *Champakam Dorairajan* (1951).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00432', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 1, 'What did the Seventh Amendment Act, 1956 provide for?', 'The **Seventh Amendment Act, 1956** gave effect to the recommendations of the **States Reorganisation Commission**, reorganising Indian states on a **linguistic basis**, abolishing the earlier four-category classification of states (Part A, B, C, D states), and introducing the present classification of States and Union Territories.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00433', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 2, 'What did the 24th Amendment Act, 1971 provide for?', 'The **24th Amendment Act, 1971** was enacted in response to *Golaknath v. State of Punjab* (1967). It affirmed Parliament''s power to **amend any part of the Constitution, including Fundamental Rights**, under Article 368, and made it obligatory for the President to give assent to constitutional amendment bills.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00434', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 3, 'What did the 25th Amendment Act, 1971 introduce?', 'The **25th Amendment Act, 1971** curtailed the right to property by amending **Article 31**, providing that laws made to give effect to Article 39(b) and (c) (Directive Principles on distribution of material resources) could not be challenged on the ground of being inconsistent with Articles 14, 19, or 31, and introduced **Article 31C**, a provision examined in *Kesavananda Bharati* (1973).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00435', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 4, 'What did the 26th Amendment Act, 1971 do?', 'The **26th Amendment Act, 1971** abolished the **privy purses** and privileges that had been guaranteed to former rulers of princely states at the time of their accession to India, removing Articles 291 and 362 and amending Article 363A.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00436', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 5, 'What is the significance of the 42nd Amendment Act, 1976?', 'The **42nd Amendment Act, 1976**, often called the **''Mini-Constitution''**, made sweeping changes including: adding **''Socialist'' and ''Secular''** to the Preamble, inserting **Fundamental Duties (Article 51A)**, giving Directive Principles primacy over Fundamental Rights (later partly struck down in *Minerva Mills*, 1980), extending the Lok Sabha and State Assembly terms to **six years** (later restored to five by the 44th Amendment), and curtailing judicial review of constitutional amendments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00437', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 6, 'What is the significance of the 44th Amendment Act, 1978?', 'The **44th Amendment Act, 1978** reversed several excesses of the 42nd Amendment following the post-Emergency political shift. It **removed the right to property** from Part III (replacing it with Article 300A as a mere legal right), restored the term of Lok Sabha/State Assemblies to **five years**, changed ''internal disturbance'' to **''armed rebellion''** as a ground for National Emergency under Article 352, and protected **Articles 20 and 21** from suspension during Emergency.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00438', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 7, 'What did the 42nd Amendment Act, 1976 change regarding judicial review of constitutional amendments, and what was its ultimate fate?', 'The **42nd Amendment** inserted clauses in Article 368 declaring that constitutional amendments **could not be questioned in any court on any ground**, seeking to place the amending power beyond judicial review entirely. This provision was **struck down** by the Supreme Court in *Minerva Mills v. Union of India* (1980) as violating the basic structure doctrine, since judicial review itself is part of the basic structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00439', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 8, 'What did the 52nd Amendment Act, 1985 introduce?', 'The **52nd Amendment Act, 1985** inserted the **Tenth Schedule**, introducing the **anti-defection law**, which provides for the disqualification of members of Parliament and State Legislatures on grounds of defection from their political party.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00440', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 9, 'What did the 61st Amendment Act, 1988 provide for?', 'The **61st Amendment Act, 1988** reduced the **voting age** from 21 years to **18 years** for elections to the Lok Sabha and State Legislative Assemblies, by amending Article 326.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00441', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 10, 'What did the 73rd and 74th Amendment Acts, 1992 achieve?', 'The **73rd Amendment Act, 1992** gave constitutional status to **Panchayati Raj institutions** (rural local self-government) by inserting Part IX and the Eleventh Schedule.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00442', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 11, 'What did the 86th Amendment Act, 2002 introduce?', 'The **86th Amendment Act, 2002** inserted **Article 21A**, making the **right to free and compulsory education** for children aged 6-14 years a Fundamental Right, amended **Article 45** to focus on early childhood care for children below 6, and added a new **Fundamental Duty under Article 51A(k)** requiring parents/guardians to provide educational opportunities to their children.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00443', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 12, 'What did the 88th Amendment Act, 2003 provide for?', 'The **88th Amendment Act, 2003** inserted **Article 268A** and a new entry in the Union List to enable Parliament to levy a **service tax**, with the proceeds being collected and appropriated by both the Union and the States (this provision became largely redundant following the GST regime introduced by the 101st Amendment).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00444', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 13, 'What did the 97th Amendment Act, 2011 provide for?', 'The **97th Amendment Act, 2011** added the words **''or cooperative societies''** to Article 19(1)(c), inserted **Article 43B** (a Directive Principle promoting cooperative societies), and added a new **Part IXB (Articles 243ZH-243ZT)** dealing with the constitution, functioning, and regulation of cooperative societies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00445', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 14, 'What is the significance of the 99th Amendment Act, 2014, and what happened to it?', 'The **99th Amendment Act, 2014** sought to replace the **collegium system** of judicial appointments with the **National Judicial Appointments Commission (NJAC)**. It was struck down as unconstitutional by the Supreme Court in *Supreme Court Advocates-on-Record Association v. Union of India* (2015), for violating the basic structure principle of **judicial independence**, reviving the collegium system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00446', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 15, 'What did the 101st Amendment Act, 2016 introduce?', 'The **101st Amendment Act, 2016** introduced the **Goods and Services Tax (GST)** regime in India, inserting **Article 246A** (granting concurrent power to Parliament and State Legislatures to legislate on GST), **Article 269A** (dealing with inter-State GST), and establishing the **GST Council** under **Article 279A** as a joint forum of the Union and States to recommend GST rates and related matters.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00447', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 16, 'What did the 102nd Amendment Act, 2018 provide for?', 'The **102nd Amendment Act, 2018** inserted **Articles 338B and 342A**, granting constitutional status to the **National Commission for Backward Classes (NCBC)** and empowering the President to notify a list of socially and educationally backward classes for each State/Union Territory.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00448', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 17, 'What did the 103rd Amendment Act, 2019 introduce?', 'The **103rd Amendment Act, 2019** introduced **10% reservation for Economically Weaker Sections (EWS)** among the general (unreserved) category in public employment and higher education, by inserting **Articles 15(6) and 16(6)**. Its constitutional validity was upheld by a majority of the Supreme Court in *Janhit Abhiyan v. Union of India* (2022).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00449', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 18, 'What did the 104th Amendment Act, 2019 provide for?', 'The **104th Amendment Act, 2019** extended the reservation of seats for **Scheduled Castes and Scheduled Tribes** in the Lok Sabha and State Legislative Assemblies for a further period (until 2030), while **discontinuing the reservation of seats for the Anglo-Indian community** (the President''s and Governors'' power of nomination of Anglo-Indian members was also removed).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00450', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 19, 'What did the 105th Amendment Act, 2021 provide for?', 'The **105th Amendment Act, 2021** restored the power of **State Governments and Union Territories to prepare and maintain their own lists of socially and educationally backward classes (OBCs)**, following the Supreme Court''s interpretation in *Maratha Reservation case* that only the Centre could identify such classes after the 102nd Amendment — this amendment clarified and reversed that restrictive reading.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00451', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 20, 'What is a ''Constitutional Amendment Bill'' and what special majority does it require under Article 368?', 'A **Constitutional Amendment Bill** amending provisions covered by **Article 368** generally requires a **''special majority''** — a majority of the **total membership** of each House of Parliament, and a majority of **not less than two-thirds of members present and voting** in each House — and must be passed by each House **separately** (no joint sitting provision applies to constitutional amendment bills, unlike ordinary legislation under Article 108).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00452', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 21, 'Which category of constitutional amendments additionally requires ratification by State Legislatures?', 'Amendments affecting **''federal provisions''** — such as the election of the President, the extent of executive power of the Union/States, provisions relating to the Supreme Court/High Courts, distribution of legislative powers between Union and States, and the amending power itself (Article 368) — require, in addition to the special majority in Parliament, **ratification by not less than one-half of the State Legislatures** through a simple majority resolution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00453', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 22, 'What is the significance of the 9th Schedule after I.R. Coelho v. State of Tamil Nadu (2007)?', 'Following ***I.R. Coelho v. State of Tamil Nadu* (2007)**, laws placed in the **Ninth Schedule after 24 April 1973** are no longer automatically immune from judicial review; they can be struck down if found to violate Fundamental Rights that form part of the **basic structure** of the Constitution, significantly reducing the Ninth Schedule''s earlier blanket protective effect.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00454', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 23, 'What is the ''Tenth Schedule'' of the Constitution, and when was it inserted?', 'The **Tenth Schedule**, inserted by the **52nd Amendment Act, 1985**, contains provisions relating to **disqualification on grounds of defection** for members of Parliament and State Legislatures, laying down the circumstances in which a member is disqualified and the procedure for deciding such disqualification questions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00455', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 24, 'What is the ''Eleventh Schedule'' of the Constitution?', 'The **Eleventh Schedule**, inserted by the **73rd Amendment Act, 1992**, enumerates **29 subjects** (such as agriculture, land improvement, minor irrigation, and rural housing) that may be entrusted to **Panchayats** for the purpose of enabling them to function as institutions of local self-government.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00456', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 25, 'What is the ''Twelfth Schedule'' of the Constitution?', 'The **Twelfth Schedule**, inserted by the **74th Amendment Act, 1992**, enumerates **18 functional items** (such as urban planning, water supply, and solid waste management) that may be entrusted to **Municipalities** under Article 243W.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00457', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 26, 'What is the procedure and significance of the ''Eighth Schedule'' and its amendments over time?', 'The **Eighth Schedule** lists the **officially recognised languages** of India, originally containing 14 languages; through subsequent constitutional amendments (such as the 21st, 71st, and 92nd Amendments), the list has been expanded to its current total of **22 languages**, including additions like Sindhi, Konkani, Manipuri, Nepali, Bodo, Dogri, Maithili, and Santhali.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00458', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 27, 'What is the significance of the 36th Amendment Act, 1975?', 'The **36th Amendment Act, 1975** made **Sikkim** a full-fledged State of the Indian Union, inserting it as the 22nd State by amending the First and Fourth Schedules, following the Sikkim Assembly''s resolution and a referendum in favour of merger with India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00459', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 28, 'What did the 42nd Amendment Act change regarding the word ''Secular'' and ''Socialist'' in the Preamble?', 'The **42nd Amendment Act, 1976** inserted the words **''Socialist''** and **''Secular''** into the Preamble, changing the description of India from ''Sovereign Democratic Republic'' to **''Sovereign Socialist Secular Democratic Republic''**, reflecting the state''s commitment to social and economic justice and equal treatment of all religions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00460', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 29, 'What is the procedure for formation of new states under Article 3, and what majority does it require?', '**Article 3** empowers Parliament, by a **simple majority** (ordinary legislative process, not Article 368''s special majority), to form a new State by separation of territory, uniting states, or altering boundaries/names of existing states — though a Bill for this purpose can be introduced only on the **President''s recommendation**, and the President must refer it to the affected State Legislature(s) for their views (though these views are not binding).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00461', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 30, 'What is the distinction between amendment under Article 3 and amendment under Article 368?', '**Article 3** deals specifically with the **reorganisation of states** (formation of new states, alteration of boundaries/names) and is passed by **simple majority**, and is explicitly stated **not to be deemed an amendment** of the Constitution under Article 368, even though it changes the First Schedule.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00462', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 31, 'What is the significance of the 73rd and 74th Amendments mandating reservation for women in local bodies?', 'The **73rd and 74th Amendment Acts, 1992** mandated **not less than one-third reservation of seats** (including chairperson positions) for **women** in Panchayats and Municipalities, marking one of the earliest and most significant constitutional measures for women''s political representation at the grassroots level in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00463', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 32, 'What did the 106th Amendment Act, 2023 provide for?', 'The **106th Amendment Act, 2023**, known as the **''Nari Shakti Vandan Adhiniyam''**, provides for the reservation of **one-third of seats** for women in the Lok Sabha, State Legislative Assemblies, and the Legislative Assembly of the National Capital Territory of Delhi, to be implemented after the next delimitation exercise following the relevant census.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00464', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 33, 'What is the historical significance of the 39th Amendment Act, 1975?', 'The **39th Amendment Act, 1975**, enacted during the Emergency, placed the election of the **President, Vice-President, Prime Minister, and Speaker of the Lok Sabha** beyond the scrutiny of courts. Its key clause relating to the Prime Minister''s election was later struck down by the Supreme Court in *Indira Nehru Gandhi v. Raj Narain* (1975) as violative of the basic structure principles of free and fair elections and rule of law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00465', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 34, 'What is the procedure under Article 4 for consequential amendments to the First and Fourth Schedules?', '**Article 4** provides that laws made under Articles 2 and 3 (admission/establishment of new states, alteration of boundaries) may contain **supplemental, incidental, and consequential provisions**, including amendments to the **First Schedule** (names/territories of states) and **Fourth Schedule** (allocation of Rajya Sabha seats), and such laws are **not treated as amendments** under Article 368.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00466', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 35, 'What are the three categories of subject matter for constitutional amendment under Article 368, classified by the type of majority required?', 'Constitutional amendments fall into three categories: those passable by **simple majority** (not technically under Article 368 at all, e.g., changes to Second Schedule emoluments, or Article 3 matters), those requiring a **special majority** in each House of Parliament alone (most provisions), and those requiring a **special majority plus ratification by at least half the State Legislatures** (federal provisions, as listed in the proviso to Article 368(2)).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00467', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 36, 'What is the significance of the 42nd Amendment reducing the quorum requirement, and was this retained?', 'The **42nd Amendment Act, 1976** omitted the quorum requirement under **Article 100**, removing the earlier stipulation of one-tenth membership needed to constitute a sitting of either House — a procedural change that, unlike several other 42nd Amendment provisions, was **not reversed** by the 44th Amendment and remains part of the Constitution today in modified form governing quorum through separate rules.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00468', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 37, 'What is the ''Constitution (One Hundred and First Amendment) Act, 2016'' GST Council''s composition and voting mechanism?', 'Under **Article 279A**, inserted by the 101st Amendment, the **GST Council** comprises the Union Finance Minister (Chairperson), the Union Minister of State for Finance, and the Finance/nominated Minister of each State. Decisions are taken by a majority of **not less than three-fourths of weighted votes**, with the Centre having **one-third** weightage and all States together having **two-thirds** weightage of votes cast.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00469', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 38, 'What is the historical background and significance of the 7th Amendment Act''s reorganisation on linguistic lines?', 'The **States Reorganisation Act, 1956**, given effect by the **Seventh Amendment Act, 1956**, followed the recommendations of the **Fazal Ali Commission (States Reorganisation Commission)**, which examined and largely accepted the case for reorganising Indian states primarily along **linguistic lines**, replacing the earlier Part A/B/C/D classification with the current States and Union Territories structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00470', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 39, 'What are ''Union Territories'' and how are they administered under Article 239?', '**Article 239** provides that every **Union Territory** is administered by the **President**, acting through an **Administrator** (or Lieutenant Governor, in certain UTs) appointed by him, to such extent as he thinks fit — distinguishing their governance structure from States, which have their own elected governments headed by a Governor acting typically on ministerial aid and advice.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00471', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 40, 'What is the special constitutional position of the National Capital Territory of Delhi under Article 239AA?', '**Article 239AA**, inserted by the **69th Amendment Act, 1991**, grants Delhi a **special status**, establishing a Legislative Assembly and Council of Ministers with an elected Chief Minister, while reserving matters of **public order, police, and land** exclusively for the Union/Lieutenant Governor, a division of power clarified and litigated in *Government of NCT of Delhi v. Union of India* (2018 and 2023).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00472', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 41, 'What amendment introduced the National Commission for Scheduled Castes and Scheduled Tribes as separate bodies?', 'The **89th Amendment Act, 2003** bifurcated the single National Commission for Scheduled Castes and Scheduled Tribes (under Article 338) into two **separate commissions** — the **National Commission for Scheduled Castes (Article 338)** and the **National Commission for Scheduled Tribes (Article 338A)** — to allow focused attention on the distinct concerns of each community.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00473', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 42, 'What amendment inserted Article 338A for Scheduled Tribes, and is this distinct from Article 342?', 'The **89th Amendment Act, 2003** inserted **Article 338A**, establishing the **National Commission for Scheduled Tribes** as a distinct constitutional body responsible for monitoring safeguards for STs.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00474', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 43, 'What is the significance of the 46th Amendment Act, 1982 for sales tax law?', 'The **46th Amendment Act, 1982** inserted **Article 366(29A)**, expanding the definition of ''tax on sale or purchase of goods'' to include specific deemed sales such as works contracts, hire-purchase, and the supply of goods in the course of execution of certain contracts, addressing judicial rulings that had previously narrowed the scope of sales tax on composite transactions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00475', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 44, 'What is the significance of the 42nd Amendment adding ''environment protection'' as a constitutional value?', 'The **42nd Amendment Act, 1976** inserted **Article 48A** (a Directive Principle requiring the State to protect and improve the environment and safeguard forests and wildlife) and **Article 51A(g)** (a Fundamental Duty requiring every citizen to protect the natural environment), together forming the constitutional foundation for India''s environmental jurisprudence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00476', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 45, 'What is the significance of the 42nd Amendment''s insertion of Article 323A and 323B regarding tribunals?', 'The **42nd Amendment Act, 1976** inserted **Articles 323A and 323B**, enabling Parliament and State Legislatures to establish **administrative and other tribunals** for adjudication of disputes relating to specified matters such as service matters, taxation, and land reforms, aimed at reducing the burden on regular courts, though their constitution and powers remain subject to judicial review safeguards as clarified in subsequent case law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00477', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 46, 'What constitutional amendment raised the retirement age of High Court judges, and from what to what?', 'The **15th Amendment Act, 1963** raised the retirement age of **High Court judges** from **60 to 62 years**, by amending Article 217, a change that has remained unaltered since, while the Supreme Court judges'' retirement age continues to be fixed at **65 years** under Article 124.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00478', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 47, 'What is the historical significance of the 93rd Amendment Act, 2005?', 'The **93rd Amendment Act, 2005** inserted **Article 15(5)**, enabling the State to make special provisions, by law, for the advancement of socially and educationally backward classes, SCs, and STs in relation to admission to **educational institutions, including private (aided and unaided) institutions**, except minority institutions under Article 30(1) — forming the basis for reservation in private professional colleges, upheld in *Ashoka Kumar Thakur v. Union of India* (2008).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00479', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 48, 'What is the significance of the 65th Amendment Act, 1990?', 'The **65th Amendment Act, 1990** replaced the earlier Special Officer for SCs/STs (under the original Article 338) with a **multi-member National Commission for Scheduled Castes and Scheduled Tribes**, strengthening institutional oversight of safeguards for these communities, prior to its later bifurcation by the 89th Amendment in 2003.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00480', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 49, 'What is the significance of the 91st Amendment Act, 2003?', 'The **91st Amendment Act, 2003** strengthened the anti-defection framework by **omitting the exception for splits** (which earlier allowed defection by one-third of a party''s members without disqualification), limited the **size of the Council of Ministers** to a maximum of 15% of the total membership of the Lok Sabha/State Assembly, and barred defectors from holding ministerial or other remunerative political posts until re-elected.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00481', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 50, 'What is the significance of the 95th Amendment Act, 2009?', 'The **95th Amendment Act, 2009** extended the reservation of seats for the **Scheduled Castes, Scheduled Tribes, and the Anglo-Indian community** in the Lok Sabha and State Legislative Assemblies for a further period of **ten years**, i.e., up to 2020, continuing a safeguard that is periodically renewed through successive amendments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00482', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 51, 'What is the significance of the 100th Amendment Act, 2015?', 'The **100th Amendment Act, 2015** gave effect to the **Land Boundary Agreement between India and Bangladesh**, facilitating the exchange of certain enclaves between the two countries and adjustment of their respective territories by amending the First Schedule.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00483', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 52, 'What is the Right to Information Act, 2005, and what does it provide?', 'The **Right to Information Act, 2005** operationalises the citizen''s fundamental right to know (flowing from Article 19(1)(a)), empowering citizens to seek **information from public authorities**, who are mandated to respond within **30 days** (48 hours where life or liberty is involved), subject to specified exemptions under Section 8, and establishes **Information Commissions** at the Central and State levels to hear appeals.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00484', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 53, 'What is the Lokpal and Lokayuktas Act, 2013?', 'The **Lokpal and Lokayuktas Act, 2013** provides for the establishment of an independent **Lokpal at the Centre** and **Lokayuktas in the States** to inquire into allegations of corruption against public functionaries, including the Prime Minister (with certain safeguards/exclusions relating to international relations, security, and public order), ministers, and members of Parliament.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00485', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 54, 'What is the Protection of Children from Sexual Offences (POCSO) Act, 2012?', 'The **POCSO Act, 2012** is a special, gender-neutral law enacted to protect children (below **18 years**) from offences of sexual assault, sexual harassment, and pornography, providing for child-friendly procedures for reporting, recording of evidence, investigation, and trial through **Special Courts**, with enhanced punishments introduced by the 2019 amendment, including the death penalty for aggravated penetrative sexual assault.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00486', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 55, 'What is the Juvenile Justice (Care and Protection of Children) Act, 2015?', 'The **Juvenile Justice Act, 2015** replaced the 2000 Act, notably allowing children aged **16-18 years** accused of ''heinous offences'' to be tried as **adults** after assessment by a Juvenile Justice Board, following public outrage after the 2012 Delhi gang-rape case, while retaining rehabilitative and child-friendly procedures for most other offences and age groups.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00487', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 56, 'What is the significance of the Consumer Protection Act, 2019, replacing the 1986 Act?', 'The **Consumer Protection Act, 2019** strengthened consumer rights by establishing a three-tier system of **Consumer Disputes Redressal Commissions** (District, State, National), creating the **Central Consumer Protection Authority (CCPA)** to regulate unfair trade practices and misleading advertisements, and introducing specific provisions on **product liability** and e-commerce transactions, which were not adequately addressed under the earlier 1986 Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00488', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 57, 'What is the Legal Services Authorities Act, 1987?', 'The **Legal Services Authorities Act, 1987**, enacted to give effect to **Article 39A** (equal justice and free legal aid), establishes the **National Legal Services Authority (NALSA)** and corresponding State/District Legal Services Authorities to provide **free legal aid** to weaker sections of society and to organise **Lok Adalats** for the amicable settlement of disputes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00489', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 58, 'What is the significance of ''Lok Adalats'' under the Legal Services Authorities Act, 1987?', '**Lok Adalats** (''People''s Courts'') are forums for alternative dispute resolution, where pending or pre-litigation disputes are settled through **conciliation and compromise**, and an **award passed by a Lok Adalat is deemed to be a decree of a civil court, final and binding on the parties, with no appeal lying against it**, significantly reducing the burden on regular courts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00490', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 59, 'What is the Arbitration and Conciliation Act, 1996, and its significance?', 'The **Arbitration and Conciliation Act, 1996**, based substantially on the **UNCITRAL Model Law**, governs domestic and international commercial arbitration and conciliation in India, limiting judicial interference in arbitral proceedings and awards (Section 5), and has been amended multiple times (notably in 2015, 2019, and 2021) to improve the speed and efficiency of arbitration as a preferred mode of dispute resolution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00491', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 60, 'What is the significance of the Insolvency and Bankruptcy Code, 2016?', 'The **Insolvency and Bankruptcy Code, 2016** consolidated and replaced the earlier fragmented insolvency framework in India, establishing a time-bound **Corporate Insolvency Resolution Process (CIRP)** before the **National Company Law Tribunal (NCLT)**, aiming to maximise the value of a distressed entity''s assets and balance the interests of all stakeholders, including creditors and employees.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00492', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 61, 'What is the Advocates Act, 1961, and what body does it establish?', 'The **Advocates Act, 1961** consolidated the law relating to legal practitioners in India, establishing the **Bar Council of India** and State Bar Councils to regulate legal education, maintain professional standards and discipline among advocates, and provide for a **unified class of legal practitioners (advocates)** with the right to practise in all courts throughout India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00493', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 62, 'What is the significance of the Code of Civil Procedure, 1908, and its structure?', 'The **Code of Civil Procedure, 1908** is the principal procedural law governing civil litigation in India, consisting of a **body of Sections** (containing the fundamental provisions) and **Orders and Rules in the First Schedule** (containing procedural details), covering matters from the institution of suits to execution of decrees, including key doctrines like res judicata (Section 11) and res sub judice (Section 10).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00494', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 63, 'What are the key provisions of the Code of Criminal Procedure, 1973 (replaced by BNSS, 2023)?', 'The **Code of Criminal Procedure, 1973** laid down the procedure for investigation, inquiry, and trial of criminal offences in India, covering arrest, bail, charge-framing, and trial procedures before different classes of criminal courts. It has been **replaced by the Bharatiya Nagarik Suraksha Sanhita (BNSS), 2023**, effective from 1 July 2024, which retains much of the CrPC''s structure while introducing provisions for electronic trials, forensic investigation in serious offences, and defined timelines for various stages.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00495', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 64, 'What is the Indian Evidence Act, 1872 (replaced by the Bharatiya Sakshya Adhiniyam, 2023)?', 'The **Indian Evidence Act, 1872** governed the admissibility, relevancy, and burden of proof of evidence in Indian courts, covering concepts like relevancy of facts, examination of witnesses, and presumptions. It has been **replaced by the Bharatiya Sakshya Adhiniyam, 2023**, effective from 1 July 2024, which retains the core evidentiary framework while formally recognising **electronic and digital records** as primary evidence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00496', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 65, 'What is the significance of the three new criminal law codes that came into force on 1 July 2024?', 'Effective **1 July 2024**, India replaced its three principal criminal law statutes: the **Indian Penal Code, 1860** was replaced by the **Bharatiya Nyaya Sanhita, 2023**; the **Code of Criminal Procedure, 1973** was replaced by the **Bharatiya Nagarik Suraksha Sanhita, 2023**; and the **Indian Evidence Act, 1872** was replaced by the **Bharatiya Sakshya Adhiniyam, 2023** — introducing changes such as the repeal of sedition as a standalone offence, provisions on organised crime and terrorism, and emphasis on technology-enabled investigation and trial.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00497', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 66, 'What is the National Green Tribunal Act, 2010?', 'The **National Green Tribunal Act, 2010** established the **National Green Tribunal (NGT)**, a specialised body for the effective and expeditious disposal of cases relating to **environmental protection, conservation of forests, and other natural resources**, including enforcement of legal rights relating to the environment, applying principles of sustainable development, the precautionary principle, and the polluter pays principle.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00498', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 67, 'What is the Right of Children to Free and Compulsory Education Act, 2009?', 'The **Right of Children to Free and Compulsory Education (RTE) Act, 2009** was enacted to give effect to **Article 21A** of the Constitution, mandating free and compulsory education for children aged **6 to 14 years**, and requiring private unaided schools to reserve **at least 25% of seats** at the entry level for children from disadvantaged groups and weaker sections.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00499', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 68, 'What is the significance of the Mental Healthcare Act, 2017?', 'The **Mental Healthcare Act, 2017** shifted India''s approach to mental illness from a custodial to a **rights-based model**, recognising the right of every person to access mental healthcare, decriminalising attempted suicide (Section 115, creating a presumption against prosecution under the erstwhile Section 309 IPC), and establishing Mental Health Review Boards to protect the rights of persons with mental illness, including the right to make advance directives regarding their own treatment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('law-q00500', 'judiciary-law-bank', 'Constitutional Amendments & Legal Framework', 6, 69, 'What is the significance of the Transgender Persons (Protection of Rights) Act, 2019?', 'The **Transgender Persons (Protection of Rights) Act, 2019** provides for the recognition of transgender identity through a certificate issued by the District Magistrate, prohibits discrimination against transgender persons in employment, education, and healthcare, and was enacted in the wake of the Supreme Court''s recognition of transgender persons'' rights in ***National Legal Services Authority (NALSA) v. Union of India* (2014)**, which recognised the right to self-identify one''s gender as ''male,'' ''female,'' or ''third gender'' under Articles 14, 15, 19, and 21.', '2026-11-14T06:17:56.365Z');
